(function(){(window.PhysicaNeetYear=window.PhysicaNeetYear||{})[2017]=[{id:"neet-2017-q001",pn:1,y:"NEET 2017 \xB7 7 May",tp:"Organic Chemistry: Some Basic Principles and Techniques",st:"Purification: steam distillation",q:"The most suitable method of separation of 1 : 1 mixture of ortho and para-nitrophenols is :",o:["Steam distillation","Sublimation","Chromatography","Crystallisation"],c:0,s:`o-Nitrophenol has intramolecular H-bonding, so its molecules stay separate and it is steam volatile.
p-Nitrophenol has intermolecular H-bonding, so it is associated, less volatile and has a high boiling point.
This difference lets steam carry over o-nitrophenol only.
So steam distillation separates the mixture.`,sfig:{w:450,h:285,alt:"o-nitrophenol with an intramolecular hydrogen bond, and p-nitrophenol molecules linked by intermolecular hydrogen bonds",d:[["p","M97.3 50.0L80.0 40.0L62.7 50.0L62.7 70.0L80.0 80.0L97.3 70.0Z",""],["c",80,60,12.4,""],["l",97.3,50,102.3,41.2,""],["t",105.3,40,"O","m"],["l",111.3,36,116.3,36,""],["t",127.3,40,"H","m"],["t",145.3,40,"\u03B4+","s"],["l",97.3,70,102.3,78.8,""],["t",105.3,88,"N","m"],["l",111.3,85.8,122.3,85.8,""],["l",111.3,82.2,122.3,82.2,""],["t",129.3,88,"O","m"],["l",105.3,91,105.3,109,"a"],["t",105.3,122,"O","m"],["t",139.3,114,"\u03B4\u2013","s"],["l",141.3,46,141.3,78,"d"],["t",100,165,"o-nitrophenol","m"],["p","M59.0 215.0L52.0 202.9L38.0 202.9L31.0 215.0L38.0 227.1L52.0 227.1Z",""],["c",45,215,8.7,""],["l",31,215,25,215,""],["t",20,219,"O","m"],["l",59,215,65,215,""],["t",70,219,"N","m"],["t",8,199,"H","m"],["l",17,209,11,203,""],["l",76.1,213.2,85.1,205.2,""],["l",73.9,210.8,82.9,202.8,""],["t",91,203,"O","m"],["l",73,221,82,235,"a"],["t",85,248,"O","m"],["l",101,203,122,203,"d"],["t",131,207,"H","m"],["l",136,205,155,210,""],["p","M199.0 215.0L192.0 202.9L178.0 202.9L171.0 215.0L178.0 227.1L192.0 227.1Z",""],["c",185,215,8.7,""],["l",171,215,165,215,""],["t",160,219,"O","m"],["l",199,215,205,215,""],["t",210,219,"N","m"],["l",157,209,149,203,""],["l",216.1,213.2,225.1,205.2,""],["l",213.9,210.8,222.9,202.8,""],["t",231,203,"O","m"],["l",213,221,222,235,"a"],["t",225,248,"O","m"],["l",241,203,262,203,"d"],["t",271,207,"H","m"],["l",276,205,295,210,""],["p","M339.0 215.0L332.0 202.9L318.0 202.9L311.0 215.0L318.0 227.1L332.0 227.1Z",""],["c",325,215,8.7,""],["l",311,215,305,215,""],["t",300,219,"O","m"],["l",339,215,345,215,""],["t",350,219,"N","m"],["l",297,209,289,203,""],["l",356.1,213.2,365.1,205.2,""],["l",353.9,210.8,362.9,202.8,""],["t",371,203,"O","m"],["l",353,221,362,235,"a"],["t",365,248,"O","m"],["l",381,203,402,203,"d"],["t",411,207,"H","m"],["t",70,270,"p-nitrophenol","m"]]},sub:"Chemistry",ch:"Organic Chemistry: Some Basic Principles and Techniques"},{id:"neet-2017-q002",pn:2,y:"NEET 2017 \xB7 7 May",tp:"Biomolecules (Chemistry)",st:"Proteins: denaturation",q:"Which of the following statements is not correct?",o:["Denaturation makes the proteins more active.","Insulin maintains sugar level in the blood of a human body.","Ovalbumin is a simple food reserve in egg-white.","Blood proteins thrombin and fibrinogen are involved in blood clotting."],c:0,s:`Denaturation destroys the shape of a protein.
A protein with a damaged shape loses its biological activity.
So the statement that denaturation makes proteins more active is wrong.`,sub:"Chemistry",ch:"Biomolecules (Chemistry)"},{id:"neet-2017-q003",pn:3,y:"NEET 2017 \xB7 7 May",tp:"Aldehydes, Ketones and Carboxylic Acids",st:"Aldol condensation",q:"Of the following, which is the product formed when cyclohexanone undergoes aldol condensation followed by heating?",o:["(1)","(2)","(3)","(4)"],c:2,s:`Two cyclohexanone molecules undergo aldol addition in base. The alpha carbon of one adds to the C=O of the other.
On heating, the aldol product loses water (the OH and an alpha hydrogen), giving a C=C bond.
The product is a cyclohexylidene-cyclohexanone: one ring still has C=O and is joined by a C=C to a CH-free ring carbon of the other ring.
This is option (3).`,fig:{w:380,h:200,alt:"Four two-ring structures: (1) two rings joined by C=C each with C=O; (2) two rings joined by a single bond with OH on one ring and C=O on the other; (3) two rings joined by C=C with one C=O; (4) two rings joined by a single bond with OH on one ring",d:[["t",10,45,"(1)","s"],["p","M83.0 45.0L74.0 29.4L56.0 29.4L47.0 45.0L56.0 60.6L74.0 60.6Z",""],["p","M129.0 45.0L120.0 29.4L102.0 29.4L93.0 45.0L102.0 60.6L120.0 60.6Z",""],["l",83,46.6,93,46.6,""],["l",83,43.4,93,43.4,""],["l",72.4,60.6,72.4,67.6,""],["l",75.6,60.6,75.6,67.6,""],["t",74,81.6,"O","m"],["l",100.4,60.6,100.4,67.6,""],["l",103.6,60.6,103.6,67.6,""],["t",102,81.6,"O","m"],["t",200,45,"(2)","s"],["p","M273.0 55.0L264.0 39.4L246.0 39.4L237.0 55.0L246.0 70.6L264.0 70.6Z",""],["p","M319.0 55.0L310.0 39.4L292.0 39.4L283.0 55.0L292.0 70.6L310.0 70.6Z",""],["l",273,55,283,55,""],["l",264,70.6,264,78.6,""],["t",264,89.6,"OH","m"],["l",293.6,39.4,293.6,32.4,""],["l",290.4,39.4,290.4,32.4,""],["t",292,30.4,"O","m"],["t",10,135,"(3)","s"],["p","M83.0 135.0L74.0 119.4L56.0 119.4L47.0 135.0L56.0 150.6L74.0 150.6Z",""],["p","M129.0 135.0L120.0 119.4L102.0 119.4L93.0 135.0L102.0 150.6L120.0 150.6Z",""],["l",83,136.6,93,136.6,""],["l",83,133.4,93,133.4,""],["l",100.4,150.6,100.4,157.6,""],["l",103.6,150.6,103.6,157.6,""],["t",102,171.6,"O","m"],["t",200,135,"(4)","s"],["p","M273.0 135.0L264.0 119.4L246.0 119.4L237.0 135.0L246.0 150.6L264.0 150.6Z",""],["p","M319.0 135.0L310.0 119.4L292.0 119.4L283.0 135.0L292.0 150.6L310.0 150.6Z",""],["l",273,135,283,135,""],["l",264,150.6,264,158.6,""],["t",264,169.6,"OH","m"]]},sfig:{w:340,h:120,alt:"Two cyclohexanone molecules lose water under OH\u207B and heat (aldol condensation) to give two rings joined by C=C with one C=O",d:[["p","M48.0 40.0L39.0 24.4L21.0 24.4L12.0 40.0L21.0 55.6L39.0 55.6Z",""],["l",48,41.6,60,41.6,""],["l",48,38.4,60,38.4,""],["t",81,44,"O + H","m"],["r",60,30,42,20,""],["t",100,67,"\u03B1","s"],["p","M132.0 76.0L123.0 60.4L105.0 60.4L96.0 76.0L105.0 91.6L123.0 91.6Z",""],["l",103.4,91.6,103.4,98.6,""],["l",106.6,91.6,106.6,98.6,""],["t",105,108.6,"O","m"],["l",150,50,215,50,"a"],["t",182,38,"OH\u207B/\u0394","ms"],["t",182,64,"aldol","ms"],["t",182,75,"Condensation","ms"],["t",182,86,"(\u2013H\u2082O)","ms"],["p","M268.0 50.0L259.0 34.4L241.0 34.4L232.0 50.0L241.0 65.6L259.0 65.6Z",""],["p","M314.0 50.0L305.0 34.4L287.0 34.4L278.0 50.0L287.0 65.6L305.0 65.6Z",""],["l",268,51.6,278,51.6,""],["l",268,48.4,278,48.4,""],["l",285.4,65.6,285.4,72.6,""],["l",288.6,65.6,288.6,72.6,""],["t",287,82.6,"O","m"]]},sub:"Chemistry",ch:"Aldehydes, Ketones and Carboxylic Acids"},{id:"neet-2017-q004",pn:4,y:"NEET 2017 \xB7 7 May",tp:"Alcohols, Phenols and Ethers",st:"Cleavage of ethers by HI",q:"The heating of phenyl-methyl ethers with HI produces.",o:["benzene","ethyl chlorides","iodobenzene","phenol"],c:3,s:`In an aryl alkyl ether, HI protonates the oxygen.
I- attacks the smaller alkyl group (CH3) by SN2. The aryl C-O bond is not broken because the C(sp2)-O bond is strong.
Products: phenol and methyl iodide.`,sfig:{w:340,h:120,alt:"Methyl phenyl ether with HI by SN2 gives phenol and methyl iodide",d:[["p","M57.0 40.0L48.5 25.3L31.5 25.3L23.0 40.0L31.5 54.7L48.5 54.7Z",""],["c",40,40,10.5,""],["l",57,40,72,40,""],["t",80,44,"O","m"],["t",104,44,"CH\u2083","m"],["p","M92 22 Q96 40 92 58","d"],["l",130,40,165,40,"a"],["t",147,32,"HI","ms"],["t",147,56,"SN\xB2","ms"],["p","M217.0 40.0L208.5 25.3L191.5 25.3L183.0 40.0L191.5 54.7L208.5 54.7Z",""],["c",200,40,10.5,""],["l",217,40,229,40,""],["t",262,44,"OH + CH\u2083I","m"],["t",40,92,"Methyl Phenyl","ms"],["t",40,104,"ether","ms"],["t",200,92,"Phenol","ms"],["t",278,92,"Methyl iodide","ms"]]},sub:"Chemistry",ch:"Alcohols, Phenols and Ethers"},{id:"neet-2017-q005",pn:5,y:"NEET 2017 \xB7 7 May",tp:"Amines",st:"Basic strength of aromatic amines",q:"The correct increasing order of basic strength for the following compounds is :",o:["II < I < III","II < III < I","III < I < II","III < II < I"],c:0,s:`Basic strength depends on how available the lone pair on N is.
Electron-donating groups (+I such as CH3) raise availability, so p-methylaniline (III) is the strongest.
Electron-withdrawing groups (-M, -I such as NO2) lower it, so p-nitroaniline (II) is the weakest.
Aniline (I) is in between.
Order: II < I < III.`,fig:{w:220,h:140,alt:"Three para-substituted anilines: (I) aniline, (II) 4-nitroaniline, (III) 4-methylaniline",d:[["p","M54.7 51.5L40.0 43.0L25.3 51.5L25.3 68.5L40.0 77.0L54.7 68.5Z",""],["c",40,60,10.5,""],["l",40,43,40,31,""],["t",40,27,"NH\u2082","m"],["t",40,128,"(I)","m"],["p","M124.7 51.5L110.0 43.0L95.3 51.5L95.3 68.5L110.0 77.0L124.7 68.5Z",""],["c",110,60,10.5,""],["l",110,43,110,31,""],["t",110,27,"NH\u2082","m"],["l",110,77,110,89,""],["t",110,102,"NO\u2082","m"],["t",110,128,"(II)","m"],["p","M194.7 51.5L180.0 43.0L165.3 51.5L165.3 68.5L180.0 77.0L194.7 68.5Z",""],["c",180,60,10.5,""],["l",180,43,180,31,""],["t",180,27,"NH\u2082","m"],["l",180,77,180,89,""],["t",180,102,"CH\u2083","m"],["t",180,128,"(III)","m"]]},sub:"Chemistry",ch:"Amines"},{id:"neet-2017-q006",pn:6,y:"NEET 2017 \xB7 7 May",tp:"Chemical Bonding and Molecular Structure",st:"Bond order",q:"Which one of the following pairs of species have the same bond order?",o:["N2, O2\u207B","CO, NO","O2, NO\u207A","CN\u207B, CO"],c:3,s:`CN\u207B and CO both have 14 electrons, so they are isoelectronic.
Isoelectronic diatomic species have the same molecular orbital configuration and the same bond order.
Bond order of both is 3.`,sub:"Chemistry",ch:"Chemical Bonding and Molecular Structure"},{id:"neet-2017-q007",pn:7,y:"NEET 2017 \xB7 7 May",tp:"Redox Reactions",st:"Reducing agents: SO2",q:"Name the gas that can readily decolourise acidified KMnO4 solution :",o:["P2O5","CO2","SO2","NO2"],c:2,s:`Acidified KMnO4 is purple because of MnO4\u207B, a strong oxidising agent.
SO2 is a reducing agent. It reduces MnO4\u207B to almost colourless Mn\xB2\u207A and itself becomes sulphate.
Reaction: KMnO4 + SO2 + H2SO4 gives K2SO4 + MnSO4 + H2O (balanced form omitted).
P2O5, CO2 and NO2 do not reduce it, so SO2 is the answer.`,sub:"Chemistry",ch:"Redox Reactions"},{id:"neet-2017-q008",pn:8,y:"NEET 2017 \xB7 7 May",tp:"The d- and f-Block Elements",st:"Actinoids: oxidation states",q:"The reason for greater range of oxidation states in actinoids is attributed to :",o:["4f and 5d levels being close in energies","the radioactive nature of actinoids","actinoid contraction","5f, 6d and 7s levels having comparable energies"],c:3,s:`In actinoids the 5f, 6d and 7s energy levels are very close.
So electrons from all three can take part in bonding.
This gives many oxidation states.`,sub:"Chemistry",ch:"The d- and f-Block Elements"},{id:"neet-2017-q009",pn:9,y:"NEET 2017 \xB7 7 May",tp:"Equilibrium",st:"Solubility product",q:"Concentration of the Ag\u207A ions in a saturated solution of Ag2C2O4 is 2.2 \xD7 10\u207B\u2074 mol L\u207B\xB9. Solubility product of Ag2C2O4 is :",o:["5.3 \xD7 10\u207B\xB9\xB2","2.42 \xD7 10\u207B\u2078","2.66 \xD7 10\u207B\xB9\xB2","4.5 \xD7 10\u207B\xB9\xB9"],c:0,s:`Ag2C2O4 \u21CC 2Ag\u207A + C2O4\xB2\u207B. If solubility is s, [Ag\u207A] = 2s and [C2O4\xB2\u207B] = s.
2s = 2.2 \xD7 10\u207B\u2074, so s = 1.1 \xD7 10\u207B\u2074 mol/L.
Ksp = (2s)\xB2 \xD7 s = 4s\xB3.
Ksp = 4 \xD7 (1.1 \xD7 10\u207B\u2074)\xB3 = 4 \xD7 1.331 \xD7 10\u207B\xB9\xB2 = 5.3 \xD7 10\u207B\xB9\xB2.`,sub:"Chemistry",ch:"Equilibrium"},{id:"neet-2017-q010",pn:10,y:"NEET 2017 \xB7 7 May",tp:"Hydrocarbons",st:"Conformations of ethane",q:"With respect to the conformers of ethane, which of the following statements is true?",o:["Both bond angles and bond length remains same","Bond angle remains same but bond length changes","Bond angle changes but bond length remains same","Both bond angle and bond length change"],c:0,s:`Conformers differ only by rotation about the C-C single bond.
No bond is broken, so bond lengths and bond angles do not change.
Only the dihedral angle changes.`,sfig:{w:300,h:150,alt:"Newman projections of ethane: staggered with hydrogens 60 degrees apart and eclipsed with front and back hydrogens overlapping; bond angle and bond length unchanged",d:[["c",70,55,14,""],["l",70,55,70,27,""],["l",70,55,45.8,69,""],["l",70,55,94.2,69,""],["l",82.1,48,94.2,41,""],["l",57.9,48,45.8,41,""],["l",70,69,70,83,""],["t",70,20,"H","m"],["t",36.2,78.5,"H","m"],["t",103.8,78.5,"H","m"],["t",103.8,39.5,"H","m"],["t",36.2,39.5,"H","m"],["t",70,98,"H","m"],["c",210,55,14,""],["l",210,55,210,27,""],["l",207.6,41.2,205.1,27.4,""],["l",210,55,185.8,69,""],["l",199.3,64,188.6,73,""],["l",210,55,234.2,69,""],["l",223.2,59.8,236.3,64.6,""],["t",216.1,20.5,"H","m"],["t",201.2,21,"H","m"],["t",173.6,73,"H","m"],["t",181.5,85.6,"H","m"],["t",240.3,83.5,"H","m"],["t",247.3,70.4,"H","m"],["t",40,118,"Bond angle \u21D2 Unchanged",""],["t",40,134,"Bond length \u21D2 Unchanged",""]]},sub:"Chemistry",ch:"Hydrocarbons"},{id:"neet-2017-q011",pn:11,y:"NEET 2017 \xB7 7 May",tp:"Haloalkanes and Haloarenes",st:"Benzyne mechanism",q:"Identify A and predict the type of reaction",o:["(1)","(2)","(3)","(4)"],c:1,s:`NaNH2 is a very strong base. It removes the H next to Br on the ring and Br\u207B leaves, giving a benzyne intermediate.
NH2\u207B adds to the benzyne and then picks up a proton from NH3.
The final product has NH2 in place of Br (meta to OCH3), so overall Br is replaced by NH2 (substitution).
This is option (2).`,fig:{w:500,h:300,alt:"3-Bromoanisole with NaNH\u2082 gives A; options (1)-(4) show anisole, 3-aminoanisole, 2-aminoanisole and 2-bromoanisole with the type of reaction",d:[["p","M136.5 52.5L120.0 43.0L103.5 52.5L103.5 71.5L120.0 81.0L136.5 71.5Z",""],["c",120,62,11.8,""],["l",120,43,120,31,""],["t",120,28,"OCH\u2083","m"],["l",136.5,71.5,146.8,77.5,""],["t",148.8,89.5,"Br","m"],["l",160,60,215,60,"a"],["t",187,52,"NaNH\u2082","ms"],["t",222,64,"A",""],["t",5,163,"(1)","s"],["p","M59.5 150.5L43.0 141.0L26.5 150.5L26.5 169.5L43.0 179.0L59.5 169.5Z",""],["c",43,160,11.8,""],["l",43,141,43,129,""],["t",43,126,"OCH\u2083","m"],["t",77,168,"and cine substitution reaction","s"],["t",280,163,"(2)","s"],["p","M334.5 150.5L318.0 141.0L301.5 150.5L301.5 169.5L318.0 179.0L334.5 169.5Z",""],["c",318,160,11.8,""],["l",318,141,318,129,""],["t",318,126,"OCH\u2083","m"],["l",334.5,169.5,344.8,175.5,""],["t",346.8,187.5,"NH\u2082","m"],["t",352,168,"and substitution reaction","s"],["t",5,253,"(3)","s"],["p","M59.5 240.5L43.0 231.0L26.5 240.5L26.5 259.5L43.0 269.0L59.5 259.5Z",""],["c",43,250,11.8,""],["l",43,231,43,219,""],["t",43,216,"OCH\u2083","m"],["l",59.5,240.5,71.6,233.5,""],["t",73.6,230.5,"NH\u2082","m"],["t",77,258,"and elimination addition reaction","s"],["t",280,253,"(4)","s"],["p","M334.5 240.5L318.0 231.0L301.5 240.5L301.5 259.5L318.0 269.0L334.5 259.5Z",""],["c",318,250,11.8,""],["l",318,231,318,219,""],["t",318,216,"OCH\u2083","m"],["l",334.5,240.5,346.6,233.5,""],["t",348.6,230.5,"Br","m"],["t",352,258,"and cine substitution reaction","s"]]},sfig:{w:470,h:210,alt:"3-Bromoanisole loses NaBr and NH\u2083 to give benzyne; NH\u2083 adds to give a carbanion with NH\u2083\u207A; proton transfer gives 3-aminoanisole",d:[["p","M71.5 55.5L55.0 46.0L38.5 55.5L38.5 74.5L55.0 84.0L71.5 74.5Z",""],["c",55,65,11.8,""],["l",55,46,55,34,""],["t",55,31,"OCH\u2083","m"],["l",71.5,55.5,83.6,48.5,""],["t",85.6,45.5,"H","m"],["l",71.5,74.5,78.4,78.5,""],["t",80.4,90.5,"Br","m"],["p","M92 40 C110 50 110 82 92 92","d"],["l",122,62,180,62,"a"],["t",151,54,"NaNH\u2082","ms"],["t",151,78,"(\u2013NaBr)(\u2013NH\u2083)","ms"],["p","M241.5 55.5L225.0 46.0L208.5 55.5L208.5 74.5L225.0 84.0L241.5 74.5Z",""],["c",225,65,11.8,""],["l",225,46,225,34,""],["t",225,31,"OCH\u2083","m"],["p","M241.5 55.5 Q252 65 241.5 74.5",""],["l",276,62,322,62,"a"],["t",299,54,"NH\u2083","ms"],["p","M361.5 55.5L345.0 46.0L328.5 55.5L328.5 74.5L345.0 84.0L361.5 74.5Z",""],["c",345,65,11.8,""],["l",345,46,345,34,""],["t",345,31,"OCH\u2083","m"],["t",371.5,53.5,"\u2296",""],["l",361.5,74.5,369.5,81.5,""],["t",365.5,93.5,"\u2295NH\u2083",""],["p","M418 78 C448 76 446 36 394 40","a"],["p","M365 95 L365 135 L300 135","a"],["t",335,127,"Intra mol.","ms"],["t",335,152,"Proton transfer","ms"],["p","M251.5 140.5L235.0 131.0L218.5 140.5L218.5 159.5L235.0 169.0L251.5 159.5Z",""],["c",235,150,11.8,""],["l",235,131,235,119,""],["t",235,116,"OCH\u2083","m"],["l",251.5,159.5,259.5,166.5,""],["t",261.5,178.5,"NH\u2082",""],["t",257.5,168.5,"\xB7\xB7","ms"],["p","M270 46 C258 38 250 44 252 55","a"]]},sub:"Chemistry",ch:"Haloalkanes and Haloarenes"},{id:"neet-2017-q012",pn:12,y:"NEET 2017 \xB7 7 May",tp:"Environmental Chemistry",st:"Air pollutants: CO sink",q:"Which of the following is sink for CO?",o:["Plants","Haemoglobin","Micro organisms present in the soil","Oceans"],c:2,s:`Soil is a natural sink for carbon monoxide.
Soil micro-organisms take up and remove CO from the air.`,sub:"Chemistry",ch:"Environmental Chemistry"},{id:"neet-2017-q013",pn:13,y:"NEET 2017 \xB7 7 May",tp:"The p-Block Elements",st:"Oxoanions of sulphur",q:"In which pair of ions both the species contain S \u2013 S bond?",o:["S4O6\xB2\u207B, S2O7\xB2\u207B","S2O7\xB2\u207B, S2O3\xB2\u207B","S4O6\xB2\u207B, S2O3\xB2\u207B","S2O7\xB2\u207B, S2O8\xB2\u207B"],c:2,s:`S4O6\xB2\u207B (tetrathionate) has an S-S-S-S chain between two SO3 ends, so it has S-S bonds.
S2O3\xB2\u207B (thiosulphate) has one S attached to the central S, so it has an S-S bond.
S2O7\xB2\u207B (pyrosulphate) and S2O8\xB2\u207B (peroxodisulphate) have S-O-S or S-O-O-S links and no S-S bond.
So the pair is S4O6\xB2\u207B and S2O3\xB2\u207B.`,sfig:{w:350,h:120,alt:"S\u2084O\u2086\xB2\u207B with an S\u2013S\u2013S\u2013S chain, each end sulphur carrying two double-bonded O and one O\u207B; S\u2082O\u2083\xB2\u207B with a central S bonded to O\u207B, O\u207B, =O and a single-bonded S",d:[["t",100,18,"S\u2084O\u2086\xB2\u207B","m"],["t",20,74,"O","m"],["l",15,61,25,61,""],["l",30,70,45,70,""],["t",60,74,"S","m"],["l",67,70,93,70,""],["t",100,74,"S","m"],["l",107,70,133,70,""],["t",140,74,"S","m"],["l",147,70,173,70,""],["t",180,74,"S","m"],["l",61.6,63,61.6,50,""],["l",58.4,63,58.4,50,""],["t",60,46,"O","m"],["l",58.4,77,58.4,90,""],["l",61.6,77,61.6,90,""],["t",60,104,"O","m"],["l",181.6,63,181.6,50,""],["l",178.4,63,178.4,50,""],["t",180,46,"O","m"],["l",178.4,77,178.4,90,""],["l",181.6,77,181.6,90,""],["t",180,104,"O","m"],["l",193,70,207,70,""],["t",220,74,"O","m"],["l",215,61,225,61,""],["t",300,18,"S\u2082O\u2083\xB2\u207B","m"],["t",300,74,"S","m"],["t",260,74,"O","m"],["l",255,61,265,61,""],["l",267,70,292,70,""],["l",308,70,333,70,""],["t",340,74,"O","m"],["l",335,61,345,61,""],["l",301.6,63,301.6,50,""],["l",298.4,63,298.4,50,""],["t",300,46,"O","m"],["l",298.4,77,298.4,90,""],["l",301.6,77,301.6,90,""],["t",300,104,"S","m"]]},sub:"Chemistry",ch:"The p-Block Elements"},{id:"neet-2017-q014",pn:14,y:"NEET 2017 \xB7 7 May",tp:"Coordination Compounds",st:"Hybridisation in complexes",q:"Pick out the correct statement with respect to [Mn(CN)6]\xB3\u207B :",o:["It is dsp\xB2 hybridised and square planar","It is sp\xB3d\xB2 hybridised and octahedral","It is sp\xB3d\xB2 hybridised and tetrahedral","It is d\xB2sp\xB3 hybridised and octahedral"],c:3,s:`Mn is 3d\u20754s\xB2, so Mn\xB3\u207A is 3d\u2074.
CN\u207B is a strong field ligand, so the four d electrons pair up in the t2g orbitals, leaving two 3d orbitals empty.
Two 3d, one 4s and three 4p orbitals mix to give d\xB2sp\xB3 hybrids.
Six CN\u207B bond to it, so the shape is octahedral (inner orbital complex).`,sfig:{w:340,h:130,alt:"Orbital boxes of Mn\xB3\u207A 3d\u2074 with four unpaired electrons splitting into two empty-pair pattern for d\xB2sp\xB3 inner octahedral hybridisation, n = 2",d:[["r",10,50,20,20,""],["t",20,64,"\u2191","m"],["r",30,50,20,20,""],["t",40,64,"\u2191","m"],["r",50,50,20,20,""],["t",60,64,"\u2191","m"],["r",70,50,20,20,""],["t",80,64,"\u2191","m"],["r",90,50,20,20,""],["t",100,64,"","m"],["l",112,60,150,60,""],["l",150,60,175,28,""],["l",150,60,175,92,""],["r",180,8,20,20,""],["t",190,22,"\u2191","m"],["r",180,82,20,20,""],["t",190,96,"\u21C5","m"],["r",200,82,20,20,""],["t",210,96,"\u2191","m"],["r",220,82,20,20,""],["t",230,96,"\u2191","m"],["t",215,16,"d\xB2 sp\xB3",""],["t",215,32,"inner octahedral",""],["t",215,48,"n = 2",""]]},sub:"Chemistry",ch:"Coordination Compounds"},{id:"neet-2017-q015",pn:15,y:"NEET 2017 \xB7 7 May",tp:"Equilibrium",st:"Combining equilibrium constants",q:`The equilibrium constants of the following are :
N2 + 3H2 \u21CC 2NH3 (K1)
N2 + O2 \u21CC 2NO (K2)
H2 + \xBDO2 \u2192 H2O (K3)
The equilibrium constant (K) of the reaction : 2NH3 + (5)/(2) O2 \u21CC 2NO + 3H2O, will be :`,o:["K2\xB2 K3/K1","K1 K3\xB3/K2","K2 K3\xB3/K1","K2 K3/K1"],c:2,s:`Target: 2NH3 + 5/2 O2 gives 2NO + 3H2O.
Reverse equation 1 (K becomes 1/K1): 2NH3 gives N2 + 3H2.
Add equation 2 (K2): N2 + O2 gives 2NO.
Add 3 \xD7 equation 3 (K becomes K3\xB3): 3H2 + 3/2 O2 gives 3H2O.
Adding: 2NH3 + 5/2 O2 gives 2NO + 3H2O.
When reactions are added, K values multiply: K = K2 \xD7 K3\xB3 / K1.`,sub:"Chemistry",ch:"Equilibrium"},{id:"neet-2017-q016",pn:16,y:"NEET 2017 \xB7 7 May",tp:"The p-Block Elements",st:"Interhalogen compounds: geometry",q:`Match the interhalogen compounds of column I with the geometry in column II and assign the correct code.
Column I: (a) XX\u2032 (b) XX\u20323 (c) XX\u20325 (d) XX\u20327
Column II: (i) T-shape (ii) Pentagonal bipyramidal (iii) Linear (iv) Square-pyramidal (v) Tetrahedral
Code (a)(b)(c)(d):`,o:["(a)-(iv), (b)-(iii), (c)-(ii), (d)-(i)","(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)","(a)-(iii), (b)-(i), (c)-(iv), (d)-(ii)","(a)-(v), (b)-(iv), (c)-(iii), (d)-(ii)"],c:2,s:`XX\u2032 is diatomic, so it is linear: (a)-(iii).
XX\u20323 has sp\xB3d hybridisation with 2 lone pairs, so T-shape: (b)-(i).
XX\u20325 has sp\xB3d\xB2 hybridisation with 1 lone pair, so square pyramidal: (c)-(iv).
XX\u20327 has sp\xB3d\xB3 hybridisation with no lone pair, so pentagonal bipyramidal: (d)-(ii).
This is option (3).`,sub:"Chemistry",ch:"The p-Block Elements"},{id:"neet-2017-q017",pn:17,y:"NEET 2017 \xB7 7 May",tp:"Chemistry in Everyday Life",st:"Antiseptics",q:"Mixture of chloroxylenol and terpineol acts as :",o:["antibiotic","analgesic","antiseptic","antipyretic"],c:2,s:`A mixture of chloroxylenol and terpineol is the common antiseptic liquid used on cuts and wounds.
So it acts as an antiseptic.`,sub:"Chemistry",ch:"Chemistry in Everyday Life"},{id:"neet-2017-q018",pn:18,y:"NEET 2017 \xB7 7 May",tp:"The p-Block Elements",st:"Inert pair effect",q:"It is because of inability of ns\xB2 electrons of the valence shell to participate in bonding that :",o:["Sn\u2074\u207A is reducing while Pb\u2074\u207A is oxidising","Sn\xB2\u207A is reducing while Pb\u2074\u207A is oxidising","Sn\xB2\u207A is oxidising while Pb\u2074\u207A is reducing","Sn\xB2\u207A and Pb\xB2\u207A are both oxidising and reducing"],c:1,s:`The ns\xB2 electrons staying out of bonding is the inert pair effect.
It makes the +2 state more stable down the group, so Pb\xB2\u207A is stable and Pb\u2074\u207A is not.
Pb\u2074\u207A tends to gain electrons to become Pb\xB2\u207A, so it is an oxidising agent.
For tin, the +4 state is more stable, so Sn\xB2\u207A tends to lose electrons and is a reducing agent.`,sub:"Chemistry",ch:"The p-Block Elements"},{id:"neet-2017-q019",pn:19,y:"NEET 2017 \xB7 7 May",tp:"The d- and f-Block Elements",st:"Extraction of silver",q:"Extraction of gold and silver involves leaching with CN\u207B ion. Silver is later recovered by :",o:["displacement with Zn","liquation","distillation","zone refining"],c:0,s:`Silver ore is leached with NaCN solution, forming the soluble complex Na[Ag(CN)2].
Zinc is more reactive than silver, so it displaces silver from the complex.
Reaction: 2Na[Ag(CN)2] + Zn gives Na2[Zn(CN)4] + 2Ag.`,sfig:{w:290,h:110,alt:"Ag\u2082S with NaCN gives Na[Ag(CN)\u2082] + Na\u2082S; then Zn gives Ag + Na\u2082[Zn(CN)\u2084]",d:[["t",10,30,"Ag\u2082S",""],["l",50,26,100,26,"a"],["t",75,18,"NaCN","ms"],["t",106,30,"Na [Ag(CN)\u2082] + Na\u2082S",""],["l",130,40,130,70,"a"],["t",138,60,"Zn",""],["t",106,95,"Ag + Na\u2082 [Zn(CN)\u2084]",""]]},sub:"Chemistry",ch:"The d- and f-Block Elements"},{id:"neet-2017-q020",pn:20,y:"NEET 2017 \xB7 7 May",tp:"Equilibrium",st:"Kp and Boyle's law",q:`A 20 litre container at 400 K contains CO2(g) at pressure 0.4 atm and an excess of SrO (neglect the volume of solid SrO). The volume of the container is now decreased by moving the movable piston fitted in the container. The maximum volume of the container, when pressure of CO2 attains its maximum value, will be :
(Given that : SrCO3(s) \u21CC SrO(s) + CO2(g), Kp = 1.6 atm)`,o:["2 litre","5 litre","10 litre","4 litre"],c:1,s:`For SrCO3(s) \u21CC SrO(s) + CO2(g), Kp = P(CO2).
So the highest pressure CO2 can have is 1.6 atm; beyond that SrCO3 forms.
Up to this point only the gas is compressed at constant T, so P1V1 = P2V2.
0.4 \xD7 20 = 1.6 \xD7 V2, so V2 = 5 L.`,sub:"Chemistry",ch:"Equilibrium"},{id:"neet-2017-q021",pn:21,y:"NEET 2017 \xB7 7 May",tp:"The Solid State",st:"Point defects",q:"Which is the incorrect statement ?",o:["Frenkel defect is favoured in those ionic compounds in which sizes of cation and anions are almost equal","FeO0.98 has non stoichiometric metal deficiency defect","Density decreases in case of crystals with Schottky's defect","NaCl(s) is insulator, silicon is semiconductor, silver is conductor, quartz is piezo electric crystal"],c:0,s:`Frenkel defect needs a cation small enough to move into an interstitial site, so the cation and anion sizes must differ a lot.
So the statement that sizes are almost equal is wrong.
The others are correct: Fe deficiency in FeO0.98, lower density with Schottky defect, and the given conductivity classes.`,sub:"Chemistry",ch:"The Solid State"},{id:"neet-2017-q022",pn:22,y:"NEET 2017 \xB7 7 May",tp:"Solutions",st:"Concentration terms",q:"Which of the following is dependent on temperature ?",o:["Weight percentage","Molality","Molarity","Mole fraction"],c:2,s:`Weight percentage, molality and mole fraction use masses or moles, which do not change with temperature.
Molarity = moles / volume of solution.
Volume changes with temperature, so molarity changes (it falls when T rises).`,sub:"Chemistry",ch:"Solutions"},{id:"neet-2017-q023",pn:23,y:"NEET 2017 \xB7 7 May",tp:"Coordination Compounds",st:"Ionisation isomerism and AgCl",q:"The correct order of the stoichiometries of AgCl formed when AgNO3 in excess is treated with the complexes : CoCl3.6NH3, CoCl3.5NH3, CoCl3.4NH3 respectively is -",o:["2AgCl, 3AgCl, 1AgCl","1AgCl, 3AgCl, 2AgCl","3AgCl, 1AgCl, 2AgCl","3AgCl, 2AgCl, 1AgCl"],c:3,s:`Only free Cl\u207B outside the coordination sphere precipitates with AgNO3.
CoCl3.6NH3 = [Co(NH3)6]Cl3 has 3 free Cl\u207B, so 3AgCl.
CoCl3.5NH3 = [Co(NH3)5Cl]Cl2 has 2 free Cl\u207B, so 2AgCl.
CoCl3.4NH3 = [Co(NH3)4Cl2]Cl has 1 free Cl\u207B, so 1AgCl.`,sub:"Chemistry",ch:"Coordination Compounds"},{id:"neet-2017-q024",pn:24,y:"NEET 2017 \xB7 7 May",tp:"Coordination Compounds",st:"Organometallic compounds",q:"An example of a sigma bonded organometallic compound is -",o:["Cobaltocene","Ruthenocene","Grignard's reagent","Ferrocene"],c:2,s:`Grignard's reagent R-Mg-X has a direct metal-carbon sigma bond (for example CH3-Mg-I).
Ferrocene, cobaltocene and ruthenocene hold cyclopentadienyl rings by pi bonds, so they are pi-bonded.`,sub:"Chemistry",ch:"Coordination Compounds"},{id:"neet-2017-q025",pn:25,y:"NEET 2017 \xB7 7 May",tp:"Structure of Atom",st:"Orbital energies and quantum principles",q:"Which one is the wrong statement ?",o:["The energy of 2s orbital is less than the energy of 2p orbital in case of Hydrogen like atoms","de-Broglie's wavelength is given by \u03BB = h/(mv), where m = mass of the particle, v = group velocity of the particle.","The uncertainty principle is \u0394E \xD7 \u0394t \u2265 h/(4\u03C0)","Half filled and fully filled orbitals have greater stability due to greater exchange energy, greater symmetry and more balanced arrangement"],c:0,s:`In hydrogen-like (one-electron) species, energy depends only on n.
So 2s and 2p have the same energy.
The statement that 2s is lower than 2p is wrong; the other three are correct.`,sub:"Chemistry",ch:"Structure of Atom"},{id:"neet-2017-q026",pn:26,y:"NEET 2017 \xB7 7 May",tp:"Alcohols, Phenols and Ethers",st:"Acidity of phenols",q:"Which one is the most acidic compound ?",o:["(1)","(2)","(3)","(4)"],c:0,s:`Acidic strength depends on how stable the phenoxide anion is.
NO2 groups at the ortho and para positions withdraw electrons by -M and -I effects and spread the negative charge.
2,4,6-Trinitrophenol (three NO2) gives the most stable anion.
CH3 is electron donating and destabilises the anion.
So option (1) is most acidic.`,fig:{w:440,h:125,alt:"Four phenols: (1) 2,4,6-trinitrophenol, (2) 4-methylphenol, (3) phenol, (4) 4-nitrophenol",d:[["t",5,60,"(1)","s"],["p","M91.5 50.5L75.0 41.0L58.5 50.5L58.5 69.5L75.0 79.0L91.5 69.5Z",""],["c",75,60,11.8,""],["l",75,41,75,28,""],["t",75,25,"OH","m"],["l",58.5,50.5,47.3,44,""],["t",46.3,48,"O\u2082N","e"],["l",91.5,50.5,102.7,44,""],["t",103.7,48,"NO\u2082",""],["l",75,79,75,92,""],["t",75,104,"NO\u2082","m"],["t",145,60,"(2)","s"],["p","M206.5 50.5L190.0 41.0L173.5 50.5L173.5 69.5L190.0 79.0L206.5 69.5Z",""],["c",190,60,11.8,""],["l",190,41,190,28,""],["t",190,25,"OH","m"],["l",190,79,190,92,""],["t",190,104,"CH\u2083","m"],["t",250,60,"(3)","s"],["p","M316.5 50.5L300.0 41.0L283.5 50.5L283.5 69.5L300.0 79.0L316.5 69.5Z",""],["c",300,60,11.8,""],["l",300,41,300,28,""],["t",300,25,"OH","m"],["t",355,60,"(4)","s"],["p","M416.5 50.5L400.0 41.0L383.5 50.5L383.5 69.5L400.0 79.0L416.5 69.5Z",""],["c",400,60,11.8,""],["l",400,41,400,28,""],["t",400,25,"OH","m"],["l",400,79,400,92,""],["t",400,104,"NO\u2082","m"]]},sfig:{w:300,h:125,alt:"2,4,6-trinitrophenol loses H\u207A to give its phenoxide anion with O\u207B and three nitro groups",d:[["p","M86.5 50.5L70.0 41.0L53.5 50.5L53.5 69.5L70.0 79.0L86.5 69.5Z",""],["c",70,60,11.8,""],["l",70,41,70,28,""],["t",70,25,"OH","m"],["l",53.5,50.5,42.3,44,""],["t",41.3,48,"O\u2082N","e"],["l",86.5,50.5,97.7,44,""],["t",98.7,48,"NO\u2082",""],["l",70,79,70,92,""],["t",70,104,"NO\u2082","m"],["l",125,62,175,62,"a"],["t",150,54,"\u2013H\u207A","ms"],["p","M251.5 50.5L235.0 41.0L218.5 50.5L218.5 69.5L235.0 79.0L251.5 69.5Z",""],["c",235,60,11.8,""],["l",235,41,235,28,""],["t",235,25,"O\u207B","m"],["l",218.5,50.5,207.3,44,""],["t",206.3,48,"O\u2082N","e"],["l",251.5,50.5,262.7,44,""],["t",263.7,48,"NO\u2082",""],["l",235,79,235,92,""],["t",235,104,"NO\u2082","m"]]},sub:"Chemistry",ch:"Alcohols, Phenols and Ethers"},{id:"neet-2017-q027",pn:27,y:"NEET 2017 \xB7 7 May",tp:"Chemical Kinetics",st:"First order integrated rate law",q:"A first order reaction has a specific reaction rate of 10\u207B\xB2 sec\u207B\xB9. How much time will it take for 20 g of the reactant to reduce to 5g ?",o:["693.0 sec","238.6 sec","138.6 sec","346.5 sec"],c:2,s:`For a first order reaction, k = (2.303/t) log([A]0/[A]t).
10\u207B\xB2 = (2.303/t) log(20/5) = (2.303/t) log 4.
t = 2.303 \xD7 0.6020 / 10\u207B\xB2 = 138.6 s.`,sub:"Chemistry",ch:"Chemical Kinetics"},{id:"neet-2017-q028",pn:28,y:"NEET 2017 \xB7 7 May",tp:"Aldehydes, Ketones and Carboxylic Acids",st:"Reactions of aldehydes",q:"Consider the reactions : X (C2H6O) on Cu at 573 K gives A; A with [Ag(NH3)2]\u207A in OH\u207B on warming gives a silver mirror; A with OH\u207B and heat gives Y; A with NH2\u2013NH\u2013C(=O)\u2013NH2 gives Z. Identify A, X, Y and Z",o:["A-Ethanol, X-Acetaldehyde, Y-Butanone Z-Hydrazone","A-Methoxymethane, X-Ethanoic acid, Y-Acetate ion, Z-Hydrazine","A-Methoxymethane, X-Ethanol, Y-Ethanoic acid, Z-Semicarbazide","A-Ethanal, X-Ethanol, Y-But-2-enal., Z-Semicarbazone"],c:3,s:`X is C2H6O. Passing it over Cu at 573 K gives a compound A that gives Tollens' silver mirror, so A is an aldehyde and X is a primary alcohol.
So X = ethanol (CH3CH2OH), oxidised (dehydrogenated) to A = ethanal (CH3CHO).
Ethanal with dilute OH\u207B and heat gives aldol condensation: Y = but-2-enal (CH3-CH=CH-CHO).
Ethanal with semicarbazide gives Z = ethanal semicarbazone (CH3-CH=N-NH-CO-NH2).
This is option (4).`,fig:{w:400,h:170,alt:"X (C\u2082H\u2086O) with Cu at 573 K gives A; A with [Ag(NH\u2083)\u2082]\u207A, OH\u207B, heat gives a silver mirror; A with OH\u207B, heat gives Y; A with NH\u2082\u2013NH\u2013CO\u2013NH\u2082 gives Z",d:[["t",5,60,"X (C\u2082H\u2086O)",""],["l",72,56,135,56,"a"],["t",103,43,"Cu","ms"],["t",103,72,"573 K","ms"],["l",98,63,108,49,""],["t",142,60,"A",""],["l",160,56,240,56,"a"],["t",200,43,"[Ag(NH\u2083)\u2082]\u207A","ms"],["t",200,70,"\u2013OH, \u0394","ms"],["t",248,60,"Silver mirror observed",""],["l",152,66,152,146,""],["l",152,96,240,96,"a"],["t",196,90,"\u2013OH, \u0394","ms"],["t",248,100,"Y",""],["l",152,146,300,146,"a"],["t",226,116,"O","ms"],["l",225,120,225,127,""],["l",228,120,228,127,""],["t",226,139,"NH\u2082\u2013NH\u2013C\u2013NH\u2082","ms"],["t",308,150,"Z",""]]},sub:"Chemistry",ch:"Aldehydes, Ketones and Carboxylic Acids"},{id:"neet-2017-q029",pn:29,y:"NEET 2017 \xB7 7 May",tp:"Chemical Kinetics",st:"Reaction mechanism and order",q:`Mechanism of a hypothetical reaction X2 + Y2 \u2192 2XY is given below.
(i) X2 \u2192 X + X (fast)
(ii) X + Y2 \u21CC XY + Y (slow)
(iii) X + Y \u2192 XY (fast)
The overall order of the reaction will be -`,o:["1.5","1","2","0"],c:0,s:`The slow step decides the rate: r = k[X][Y2].
X is an intermediate, so replace it using the fast first step (an equilibrium).
Kc = [X]\xB2/[X2], so [X] = (Kc[X2])^(1/2).
r = k Kc^(1/2) [X2]^(1/2) [Y2]^1.
Overall order = 1/2 + 1 = 1.5.`,sub:"Chemistry",ch:"Chemical Kinetics"},{id:"neet-2017-q030",pn:30,y:"NEET 2017 \xB7 7 May",tp:"Hydrocarbons",st:"Hydration of alkynes",q:`Predict the correct intermediate and product in the following reaction :
H3C\u2013C\u2261CH \u2192 (H2O, H2SO4, HgSO4) \u2192 Intermediate (A) \u2192 Product (B)`,o:["A : H3C\u2013C(OH)=CH2, B : H3C\u2013C(=O)\u2013CH3","A : H3C\u2013C(OSO3H)=CH2 (written with SO4), B : H3C\u2013C(=O)\u2013CH3","A : H3C\u2013C(OH)=CH2, B : H3C\u2013C(SO4)=CH2","A : H3C\u2013C(=O)\u2013CH3, B : H3C\u2013C\u2261CH"],c:0,s:`Propyne adds water in the presence of HgSO4/H2SO4 following Markovnikov's rule.
OH goes to the middle carbon, giving the enol CH3-C(OH)=CH2 as the intermediate A.
The enol is unstable and shifts to the keto form by tautomerism.
Product B is acetone, CH3-CO-CH3.`,fig:{w:420,h:150,alt:"Options as structures: (1) A is CH\u2083\u2013C(OH)=CH\u2082 and B is CH\u2083\u2013CO\u2013CH\u2083; (2) A is CH\u2083\u2013C(SO\u2084)=CH\u2082 and B is CH\u2083\u2013CO\u2013CH\u2083; (3) A is CH\u2083\u2013C(OH)=CH\u2082 and B is CH\u2083\u2013C(SO\u2084)=CH\u2082; (4) A is CH\u2083\u2013CO\u2013CH\u2083 and B is CH\u2083\u2013C\u2261CH",d:[["t",0,34,"(1)","s"],["t",22,34,"A :","s"],["t",44,34,"H\u2083C\u2013C=CH\u2082","s"],["l",69,39,69,49,""],["t",69,60,"OH","ms"],["t",112,34,"B :","s"],["t",134,34,"H\u2083C\u2013C\u2013CH\u2083","s"],["l",157.5,39,157.5,49,""],["l",160.5,39,160.5,49,""],["t",159,59,"O","ms"],["t",215,34,"(2)","s"],["t",237,34,"A :","s"],["t",259,34,"H\u2083C\u2013C=CH\u2082","s"],["l",284,39,284,49,""],["t",284,60,"SO\u2084","ms"],["t",327,34,"B :","s"],["t",349,34,"H\u2083C\u2013C\u2013CH\u2083","s"],["l",372.5,39,372.5,49,""],["l",375.5,39,375.5,49,""],["t",374,59,"O","ms"],["t",0,104,"(3)","s"],["t",22,104,"A :","s"],["t",44,104,"H\u2083C\u2013C=CH\u2082","s"],["l",69,109,69,119,""],["t",69,130,"OH","ms"],["t",112,104,"B :","s"],["t",134,104,"H\u2083C\u2013C=CH\u2082","s"],["l",159,109,159,119,""],["t",159,130,"SO\u2084","ms"],["t",215,104,"(4)","s"],["t",237,104,"A :","s"],["t",259,104,"H\u2083C\u2013C\u2013CH\u2083","s"],["l",282.5,109,282.5,119,""],["l",285.5,109,285.5,119,""],["t",284,129,"O","ms"],["t",327,104,"B :","s"],["t",349,104,"H\u2083C\u2013C\u2261CH","s"]]},sfig:{w:370,h:105,alt:"CH\u2083\u2013C\u2261CH with H\u2082O and HgSO\u2084 (Markovnikov addition) gives the enol CH\u2083\u2013C(OH)=CH\u2082 (A), which is in equilibrium by tautomerism (T) with CH\u2083\u2013CO\u2013CH\u2083 (B)",d:[["t",5,35,"CH\u2083\u2013C\u2261CH",""],["l",76,31,125,31,"a"],["t",98,23,"H\u2082O","ms"],["t",98,47,"HgSO\u2084","ms"],["t",98,59,"(Markovnikov","ms"],["t",98,71,"addition)","ms"],["t",138,35,"CH\u2083\u2013C=CH\u2082",""],["l",182,40,182,50,""],["t",182,62,"OH","ms"],["c",182,86,9,""],["t",182,90,"A","ms"],["l",222,31,259,31,""],["l",222,35,259,35,""],["p","M259 31 L251 28 M222 35 L230 38",""],["c",240,14,8,""],["t",240,18,"T","ms"],["t",268,35,"CH\u2083\u2013C\u2013CH\u2083",""],["l",311,40,311,50,""],["l",314,40,314,50,""],["t",312,62,"O","ms"],["c",312,86,9,""],["t",312,90,"B","ms"]]},sub:"Chemistry",ch:"Hydrocarbons"},{id:"neet-2017-q031",pn:31,y:"NEET 2017 \xB7 7 May",tp:"Organic Chemistry: Some Basic Principles and Techniques",st:"IUPAC nomenclature",q:"The IUPAC name of the compound H\u2013C(=O)\u2013CH(CH3)\u2013C(=O)\u2013CH=CH\u2013CH3 is -",o:["3-keto-2-methylhex-5-enal","3-keto-2-methylhex-4-enal","5-formylhex-2-en-3-one","5-methyl-4-oxohex-2en-5-al"],c:1,s:`The aldehyde group has the highest priority, so its carbon is C1.
The longest chain through it has 6 carbons: C1 CHO, C2 CH(CH3), C3 C=O, C4=C5 double bond, C6 CH3.
So: CH3 at C2, keto at C3, double bond at C4, and the name is 3-keto-2-methylhex-4-enal.`,fig:{w:130,h:100,alt:"H\u2013CO\u2013CH(CH\u2083)\u2013CO\u2013CH=CH\u2013CH\u2083 drawn as a skeletal chain",d:[["t",9,40,"H","m"],["l",16,36,25,36,""],["t",33,40,"C","m"],["l",31.4,27,31.4,16,""],["l",34.6,27,34.6,16,""],["t",33,12,"O","m"],["l",40,37,48,46,""],["l",48,46,65,36,""],["l",48,46,48,66,""],["l",65,36,82,46,""],["l",80,46,80,66,""],["l",84,46,84,66,""],["l",82,66,99,76,""],["l",66.6,36,66.6,22,""],["l",63.4,36,63.4,22,""],["t",65,18,"O","m"]]},sfig:{w:140,h:100,alt:"The same chain numbered 1 to 6 from the CHO carbon: C1 CHO, C2 with methyl, C3 with =O, C4=C5, C6 terminal",d:[["t",20,22,"CHO",""],["l",28,26,40,45,""],["l",40,45,58,35,""],["l",40,45,40,65,""],["l",58,35,75,45,""],["l",73,45,73,65,""],["l",77,45,77,65,""],["l",75,65,92,75,""],["l",59.6,35,59.6,21,""],["l",56.4,35,56.4,21,""],["t",58,17,"O","m"],["t",8,32,"1","s"],["t",30,56,"2","s"],["t",62,50,"3","s"],["t",80,48,"4","s"],["t",66,78,"5","s"],["t",98,86,"6","s"]]},sub:"Chemistry",ch:"Organic Chemistry: Some Basic Principles and Techniques"},{id:"neet-2017-q032",pn:32,y:"NEET 2017 \xB7 7 May",tp:"Electrochemistry",st:"Nernst equation",q:"In the electrochemical cell \u2013 Zn|ZnSO4(0.01M) || CuSO4(1.0 M)|Cu, the emf of this Daniel cell is E1. When the concentration of ZnSO4 is changed to 1.0 M and that of CuSO4 changed to 0.01M, the emf changes to E2. From the followings, which one is the relationship between E1 and E2 ? (Given, RT/F = 0.059).",o:["E2 = 0 \u2260 E1","E1 = E2","E1 < E2","E1 > E2"],c:3,s:`Nernst equation: E = E\xB0 \u2212 (0.059/2) log([Zn\xB2\u207A]/[Cu\xB2\u207A]).
Case 1: E1 = E\xB0 \u2212 (0.059/2) log(0.01/1) = E\xB0 + 0.059.
Case 2: E2 = E\xB0 \u2212 (0.059/2) log(1/0.01) = E\xB0 \u2212 0.059.
So E1 is larger: E1 > E2.`,sub:"Chemistry",ch:"Electrochemistry"},{id:"neet-2017-q033",pn:33,y:"NEET 2017 \xB7 7 May",tp:"Thermodynamics (Chemistry)",st:"First law: adiabatic expansion",q:"A gas is allowed to expand in a well insulated container against a constant external pressure of 2.5 atm from an initial volume of 2.50 L to a final volume of 4.50 L. The change in internal energy \u0394U of the gas in joules will be -",o:["+505 J","1136.25 J","\u2013 500 J","\u2013 505 J"],c:3,s:`Insulated container, so q = 0.
\u0394U = q + w = \u2212P\u0394V.
\u0394V = 4.50 \u2212 2.50 = 2.00 L.
\u0394U = \u22122.5 \xD7 2.00 = \u22125.0 L atm.
1 L atm \u2248 101 J, so \u0394U = \u22125 \xD7 101 = \u2212505 J.`,sub:"Chemistry",ch:"Thermodynamics (Chemistry)"},{id:"neet-2017-q034",pn:34,y:"NEET 2017 \xB7 7 May",tp:"Coordination Compounds",st:"Crystal field splitting and colour",q:"Correct increasing order for the wavelengths of absorption in the visible region for the complexes of Co\xB3\u207A is -",o:["[Co(NH3)6]\xB3\u207A, [Co(en)3]\xB3\u207A, [Co(H2O)6]\xB3\u207A","[Co(en)3]\xB3\u207A, [Co(NH3)6]\xB3\u207A, [Co(H2O)6]\xB3\u207A","[Co(H2O)6]\xB3\u207A, [Co(en)3]\xB3\u207A, [Co(NH3)6]\xB3\u207A","[Co(H2O)6]\xB3\u207A, [Co(NH3)6]\xB3\u207A, [Co(en)3]\xB3\u207A"],c:1,s:`Ligand field strength order: en > NH3 > H2O.
So splitting \u03940 is largest for en and smallest for H2O.
\u03940 = hc/\u03BB, so a larger \u03940 means a shorter wavelength absorbed.
Wavelength order: [Co(en)3]\xB3\u207A < [Co(NH3)6]\xB3\u207A < [Co(H2O)6]\xB3\u207A.`,sub:"Chemistry",ch:"Coordination Compounds"},{id:"neet-2017-q035",pn:35,y:"NEET 2017 \xB7 7 May",tp:"Organic Chemistry: Some Basic Principles and Techniques",st:"Electrophiles and nucleophiles",q:"The correct statement regarding electrophile is :",o:["Electrophile can be either neutral or positively charged species and can form a bond by accepting a pair of electrons from a nucleophile","Electrophile is a negatively charged species and can form a bond by accepting a pair of electrons form a nucleophile","Electrophile is a negatively charged species and can form a bond by accepting a pair of electrons from another electrophile","Electrophiles are generally neutral species and can form a bond by accepting a pair of electrons from a nucleophile"],c:0,s:`An electrophile is electron-loving: it accepts an electron pair from a nucleophile.
It can be positively charged (such as H\u207A, NO2\u207A) or neutral with an electron-poor atom (such as BF3).
It is not negatively charged, so only option (1) is correct.`,sub:"Chemistry",ch:"Organic Chemistry: Some Basic Principles and Techniques"},{id:"neet-2017-q036",pn:36,y:"NEET 2017 \xB7 7 May",tp:"Thermodynamics (Chemistry)",st:"Gibbs energy and spontaneity",q:"For a given reaction, \u0394H = 35.5 kJ mol\u207B\xB9 and \u0394S = 83.6 JK\u207B\xB9 mol\u207B\xB9. The reaction is spontaneous at : (Assume that \u0394H and \u0394S do not vary with temperature)",o:["T > 298 K","T < 425 K","T > 425 K","All temperatures"],c:2,s:`\u0394G = \u0394H \u2212 T\u0394S. At the changeover, \u0394G = 0.
T = \u0394H/\u0394S = 35.5 \xD7 10\xB3 / 83.6 = 424.6 K \u2248 425 K.
\u0394H and \u0394S are both positive, so \u0394G becomes negative at higher temperature.
So the reaction is spontaneous for T > 425 K.`,sub:"Chemistry",ch:"Thermodynamics (Chemistry)"},{id:"neet-2017-q037",pn:37,y:"NEET 2017 \xB7 7 May",tp:"Chemical Bonding and Molecular Structure",st:"VSEPR and shapes",q:"Which of the following pairs of compounds is isoelectronic and isostructural ?",o:["IF3, XeF2","BeCl2, XeF2","TeI2, XeF2","IBr2\u207B, XeF2"],c:3,s:`IBr2\u207B has 7 + 2\xD77 + 1 = 22 valence electrons; XeF2 has 8 + 2\xD77 = 22. So they are isoelectronic.
Both have 5 electron pairs (2 bond pairs, 3 lone pairs): sp\xB3d hybridisation.
The 3 lone pairs sit in the equatorial plane, so both are linear.
So the pair is IBr2\u207B and XeF2.`,sfig:{w:240,h:225,alt:"IBr\u2082\u207B and XeF\u2082 drawn alike: central atom with two atoms above and below in a line and three lone pairs in a plane around the centre; IBr\u2082\u207B carries a 1\u2212 charge",d:[["p","M116 7 Q108 7 108 15 L108 95 Q108 103 116 103",""],["p","M184 7 Q192 7 192 15 L192 95 Q192 103 184 103",""],["t",200,11,"\u2013","s"],["t",150,22,"Br","m"],["t",150,62,"I","m"],["t",150,98,"Br","m"],["l",150,28,150,43,""],["l",150,70,150,84,""],["l",134,46,143,53,""],["l",134,78,143,71,""],["c",127,40,1.2,"F"],["c",123,44,1.2,"F"],["c",127,76,1.2,"F"],["c",123,72,1.2,"F"],["c",178,58,1.2,"F"],["c",178,64,1.2,"F"],["l",157,58,165,58,""],["t",8,64,"IBr\u2082\u207B  sp\xB3d  linear",""],["p","M116 117 Q108 117 108 125 L108 205 Q108 213 116 213",""],["p","M184 117 Q192 117 192 125 L192 205 Q192 213 184 213",""],["t",150,132,"F","m"],["t",150,172,"Xe","m"],["t",150,208,"F","m"],["l",150,138,150,153,""],["l",150,180,150,194,""],["l",131,156,139,163,""],["l",131,188,139,181,""],["c",127,150,1.2,"F"],["c",123,154,1.2,"F"],["c",127,186,1.2,"F"],["c",123,182,1.2,"F"],["c",178,168,1.2,"F"],["c",178,174,1.2,"F"],["l",160,168,168,168,""],["t",8,174,"XeF\u2082  sp\xB3d  linear",""]]},sub:"Chemistry",ch:"Chemical Bonding and Molecular Structure"},{id:"neet-2017-q038",pn:38,y:"NEET 2017 \xB7 7 May",tp:"The d- and f-Block Elements",st:"Mercury and iodine complexes",q:"HgCl2 and I2 both when dissolved in water containing I\u207B ions pair of species formed is :",o:["Hg2I2, I\u207B","HgI2, I3\u207B","HgI2, I\u207B","HgI4\xB2\u207B, I3\u207B"],c:3,s:`HgCl2 reacts with I\u207B to give HgI2 (red precipitate).
With excess I\u207B it dissolves as the complex ion: HgI2 + 2I\u207B gives [HgI4]\xB2\u207B.
I2 dissolves in I\u207B solution by forming I3\u207B.
So the pair formed is HgI4\xB2\u207B and I3\u207B.`,sub:"Chemistry",ch:"The d- and f-Block Elements"},{id:"neet-2017-q039",pn:39,y:"NEET 2017 \xB7 7 May",tp:"Equilibrium",st:"Catalyst and equilibrium",q:"Which one of the following statements is not correct ?",o:["Coenzymes increase the catalytic activity of enzyme","Catalyst does not initiate and reaction","The value of equilibrium constant is changed in the presence of a catalyst in the reaction at equilibrium .","Enzymes catalyse mainly bio-chemical reaction."],c:2,s:`A catalyst speeds up the forward and backward reactions equally.
So it only helps the system reach equilibrium sooner; it does not change K.
The statement that K changes with a catalyst is wrong.`,sub:"Chemistry",ch:"Equilibrium"},{id:"neet-2017-q040",pn:40,y:"NEET 2017 \xB7 7 May",tp:"Electrochemistry",st:"Ionic mobility",q:"Ionic mobility of which of the following alkali metal ions is lowest when aqueous solutions of their salts are put under an electric filed?",o:["Li","Na","K","Rb"],c:0,s:`Li\u207A is the smallest ion, so it has the highest charge density.
It attracts the most water molecules, so its hydrated radius is the largest.
A large hydrated ion moves slowest, so Li\u207A has the lowest ionic mobility.`,sub:"Chemistry",ch:"Electrochemistry"},{id:"neet-2017-q041",pn:41,y:"NEET 2017 \xB7 7 May",tp:"Classification of Elements and Periodicity in Properties",st:"Electronic configuration of new elements",q:"The element Z = 114 has been discovered recently. It will belong to which of the following family/group and electronic configuration ?",o:["Nitrogen family, [Rn] 5f\xB9\u2074 6d\xB9\u2070 7s\xB2 7p\u2076","Halogen family, [Rn] 5f\xB9\u2074 6d\xB9\u2070 7s\xB2 7p\u2075","Carbon family, [Rn] 5f\xB9\u2074 6d\xB9\u2070 7s\xB2 7p\xB2","Oxygen family, [Rn] 5f\xB9\u2074 6d\xB9\u2070 7s\xB2 7p\u2074"],c:2,s:`Rn has Z = 86, so 114 \u2212 86 = 28 more electrons.
They fill 7s\xB2 (2), 5f\xB9\u2074 (14), 6d\xB9\u2070 (10) and 7p\xB2 (2) = 28.
Configuration: [Rn] 5f\xB9\u2074 6d\xB9\u2070 7s\xB2 7p\xB2.
Valence shell ns\xB2 np\xB2 means the carbon family (group 14).`,sub:"Chemistry",ch:"Classification of Elements and Periodicity in Properties"},{id:"neet-2017-q042",pn:42,y:"NEET 2017 \xB7 7 May",tp:"Hydrocarbons",st:"Acidity of hydrocarbons",q:"Which one is the correct order of acidity ?",o:["CH3\u2013CH3 > CH2=CH2 > CH3\u2013C\u2261CH > CH\u2261CH","CH2=CH2 > CH3\u2013CH=CH2 > CH3\u2013C\u2261CH > CH\u2261CH","CH\u2261CH > CH3\u2013C\u2261CH > CH2=CH2 > CH3\u2013CH3","CH\u2261CH > CH2=CH2 > CH3\u2013C\u2261CH > CH3\u2013CH3"],c:2,s:`Acidity increases with the s-character (electronegativity) of the carbon bearing the H.
sp carbon (50% s) > sp\xB2 (33%) > sp\xB3 (25%).
So alkynes are more acidic than alkenes, which are more acidic than alkanes.
In propyne the +I effect of CH3 slightly lowers acidity compared with ethyne.
Order: CH\u2261CH > CH3\u2013C\u2261CH > CH2=CH2 > CH3\u2013CH3.`,sub:"Chemistry",ch:"Hydrocarbons"},{id:"neet-2017-q043",pn:43,y:"NEET 2017 \xB7 7 May",tp:"Solutions",st:"Depression in freezing point",q:"If molality of the dilute solution is doubled, the value of molal depression constant (Kf) will be",o:["unchanged","doubled","halved","tripled"],c:0,s:`\u0394Tf = Kf \xD7 m.
Kf is a property of the solvent only (it depends on solvent's Tf and enthalpy of fusion).
It does not depend on the molality, so it stays unchanged; \u0394Tf doubles instead.`,sub:"Chemistry",ch:"Solutions"},{id:"neet-2017-q044",pn:44,y:"NEET 2017 \xB7 7 May",tp:"Chemical Bonding and Molecular Structure",st:"Shapes and bond angles",q:"The species, having bond angles of 120\xBA is",o:["BCl3","PH3","ClF3","NCl3"],c:0,s:`BCl3 has 3 bond pairs and no lone pair on B, so it is sp\xB2 and trigonal planar with 120\xB0 angles.
PH3 and NCl3 are pyramidal (lone pair), with angles near 93\xB0 and 107\xB0.
ClF3 is T-shaped, with angles near 90\xB0.`,sfig:{w:200,h:150,alt:"BCl3 trigonal planar: B at the centre with three Cl atoms 120 degrees apart.",d:[["t",100,32,"Cl","m"],["l",100,40,100,66],["t",100,84,"B","m"],["l",92,94,70,112],["l",108,94,130,112],["t",60,128,"Cl","m"],["t",140,128,"Cl","m"]]},sub:"Chemistry",ch:"Chemical Bonding and Molecular Structure"},{id:"neet-2017-q045",pn:45,y:"NEET 2017 \xB7 7 May",tp:"Amines",st:"Hoffmann bromamide reaction",q:"Which of the following reactions is appropriate for converting acetamide to methanamine ?",o:["Gabriels phthalimide synthesis","Carbylamine reaction","Hoffmann hypobromamide reaction","Stephens reaction"],c:2,s:`Acetamide CH3CONH2 has two carbons; methanamine CH3NH2 has one.
In Hoffmann bromamide degradation, an amide with Br2 and KOH (KOBr) loses its C=O carbon to give a primary amine with one carbon less.
So CH3CONH2 gives CH3NH2.`,sfig:{w:340,h:120,alt:"Acetamide CH3-C(=O)-NH2 with Br2 + 4KOH or KOBr gives methanamine CH3-NH2.",d:[["t",8,50,"CH\u2083 \u2013 C \u2013 NH\u2082",""],["l",64,56,64,72],["l",68,56,68,72],["t",66,90,"O","m"],["t",44,108,"(Acetamide)","ms"],["t",160,36,"Br\u2082 + (4) KOH","ms"],["l",118,52,206,52,"a"],["t",160,70,"Or KOBr","ms"],["t",212,50,"CH\u2083 \u2013 NH\u2082",""],["t",252,76,"(Methanamine)","ms"]]},sub:"Chemistry",ch:"Amines"},{id:"neet-2017-q046",pn:46,y:"NEET 2017 \xB7 7 May",tp:"Organisms and Populations",st:"Logistic growth",q:"Asymptote in a logistic growth curve is obtained when :",o:["K < N","The value of 'r' approaches zero","K = N","K > N"],c:2,s:`In logistic growth, dN/dt = rN(K \u2212 N)/K.
When N reaches the carrying capacity K, the factor (K \u2212 N) becomes zero, so growth stops.
The curve then flattens into the asymptote.
So the answer is K = N.`,sub:"Botany",ch:"Organisms and Populations"},{id:"neet-2017-q047",pn:47,y:"NEET 2017 \xB7 7 May",tp:"Anatomy of Flowering Plants",st:"Secondary growth",q:"The vascular cambium normally gives rise to :",o:["Periderm","Phelloderm","Primary phloem","Secondary xylem"],c:3,s:`Vascular cambium is a lateral meristem between xylem and phloem.
It cuts off secondary xylem on the inner side and secondary phloem on the outer side.
Periderm and phelloderm come from the cork cambium.
Primary phloem comes from the procambium.`,sub:"Botany",ch:"Anatomy of Flowering Plants"},{id:"neet-2017-q048",pn:48,y:"NEET 2017 \xB7 7 May",tp:"Animal Kingdom",st:"Phylum Porifera",q:"In case of poriferans, the spongocoel is lined with flagellated cells called :",o:["Mesenchymal cells","Ostia","Oscula","Choanocytes"],c:3,s:`The spongocoel and the canals of sponges are lined by choanocytes (collar cells).
Their flagella beat to create the water current.
Ostia are the small inlet pores and oscula is the outlet opening; mesenchymal cells lie between layers.`,sub:"Zoology",ch:"Animal Kingdom"},{id:"neet-2017-q049",pn:49,y:"NEET 2017 \xB7 7 May",tp:"Plant Growth and Development",st:"Plant hormones: auxins",q:"Fruit and leaf drop at early stages can be prevented by the application of",o:["Gibberellic acid","Cytokinins","Ethylene","Auxins"],c:3,s:`Abscission of young leaves and fruits is promoted by ethylene.
Auxins prevent early abscission of these young parts.
So spraying auxins prevents fruit and leaf drop.`,sub:"Botany",ch:"Plant Growth and Development"},{id:"neet-2017-q050",pn:50,y:"NEET 2017 \xB7 7 May",tp:"Biotechnology: Principles and Processes",st:"Selectable marker",q:"A gene whose expression helps to identify transformed cell is known as",o:["Structural gene","Selectable marker","Vector","Plasmid"],c:1,s:`A selectable marker gene (for example an antibiotic resistance gene) is carried on the vector.
Only transformed cells express it, so they survive on the selective medium and can be identified.
A vector and a plasmid are carriers, not the identifying gene.
Note: The paper prints no solution; this working is added here.`,sub:"Botany",ch:"Biotechnology: Principles and Processes"},{id:"neet-2017-q051",pn:51,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"Proof of DNA as genetic material",q:"The final proof for DNA as the genetic material came from the experiments of",o:["Hargobind Khorana","Griffith","Hershey and chase","Avery, Mcleod and McCarty"],c:2,s:`Griffith showed a transforming principle; Avery, MacLeod and McCarty showed it was DNA, but critics doubted.
Hershey and Chase labelled phage DNA with \xB3\xB2P and protein with \xB3\u2075S.
Only the DNA entered the bacteria and produced new phages.
This gave the final proof.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q052",pn:52,y:"NEET 2017 \xB7 7 May",tp:"Photosynthesis in Higher Plants",st:"Factors affecting photosynthesis",q:"With reference to factors affecting the rate of photosynthesis, which of the following statements is not correct ?",o:["Tomato is a greenhouse crop which can be grown in CO2-enriched atmosphere for higher yield","Light saturation for CO2 fixation occurs at 10% of full sunlight","Increasing atmospheric CO2 concentration up to 0.05% can enhance CO2 fixation rate","C3 plants respond to higher temperatures with enhanced photosynthesis while C4 plants have much lower temperature optimum"],c:3,s:`C4 plants are adapted to hot, dry conditions and have a high temperature optimum.
C3 plants have a lower temperature optimum (about 20-25 \xB0C).
So the statement is reversed and wrong.
The other three statements are correct.`,sub:"Botany",ch:"Photosynthesis in Higher Plants"},{id:"neet-2017-q053",pn:53,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"Nucleosome and chromatin",q:"The association of histone H1 with a nucleosome indicates :",o:["The DNA double helix is exposed","Transcription is occurring","DNA replication is occurring","The DNA is condensed into a Chromatin Fibre"],c:3,s:`DNA wraps around a histone octamer to form a nucleosome.
Histone H1 binds the linker DNA where it enters and leaves the nucleosome and holds it like a clip.
This packs nucleosomes into a condensed chromatin fibre.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q054",pn:54,y:"NEET 2017 \xB7 7 May",tp:"Human Reproduction",st:"Hormonal control of reproduction",q:"GnRH, a hypothalamic hormone, needed in reproduction, acts on",o:["Posterior pituitary gland and stimulates secretion of LH and relaxin","Anterior pituitary gland and stimulates secretion of LH and oxytocin","Anterior pituitary gland and stimulates secretion of LH and FSH","Posterior pituitary gland and stimulates secretion of oxytocin and FSH"],c:2,s:`GnRH (gonadotropin releasing hormone) is made by the hypothalamus.
It acts on the anterior pituitary.
There it stimulates secretion of the gonadotropins LH and FSH.`,sub:"Zoology",ch:"Human Reproduction"},{id:"neet-2017-q055",pn:55,y:"NEET 2017 \xB7 7 May",tp:"Biotechnology: Principles and Processes",st:"Gel electrophoresis",q:"DNA fragments are",o:["Either positively or negatively charged depending on their size","Positively charged","Negatively charged","Neutral"],c:2,s:`Each nucleotide has a phosphate group in the DNA backbone.
Phosphate carries a negative charge, so DNA fragments are negatively charged.
In gel electrophoresis they move toward the positive electrode.`,sub:"Botany",ch:"Biotechnology: Principles and Processes"},{id:"neet-2017-q056",pn:56,y:"NEET 2017 \xB7 7 May",tp:"Cell Cycle and Cell Division",st:"Stages of mitosis",q:"Which of the following options gives the correct sequences of events during mitosis ?",o:["condensation \u2192 arrangement at equator \u2192 centromere division \u2192 segregation \u2192 telophase","condensation \u2192 nuclear membrane disassembly \u2192 crossing over \u2192 segregation \u2192 telophase","condensation \u2192 nuclear membrane disassembly \u2192 arrangement at equator \u2192 centromere division \u2192 segregation \u2192 telophase","condensation \u2192 crossing over \u2192 nuclear membrane disassembly \u2192 segregation \u2192 telophase"],c:2,s:`Chromosomes condense in prophase.
The nuclear membrane breaks down at the end of prophase.
Chromosomes line up at the equator in metaphase.
Centromeres divide and chromatids segregate in anaphase.
Telophase follows.
Crossing over happens only in meiosis, so it is not in the sequence.`,sub:"Botany",ch:"Cell Cycle and Cell Division"},{id:"neet-2017-q057",pn:57,y:"NEET 2017 \xB7 7 May",tp:"Breathing and Exchange of Gases",st:"Lung volumes",q:"Lungs are made up of air-filled sacs, the alveoli. They do not collapse even after forceful expiration, because of :",o:["Expiratory Reserve Volume","Residual Volume","Inspiratory Reserve Volume","Tidal Volume"],c:1,s:`After a forceful expiration some air (about 1100-1200 mL) still stays in the lungs.
This is the residual volume.
It keeps the alveoli open.`,sub:"Zoology",ch:"Breathing and Exchange of Gases"},{id:"neet-2017-q058",pn:58,y:"NEET 2017 \xB7 7 May",tp:"Biomolecules (Biology)",st:"Enzyme parts",q:"Which one of the following statements is correct with reference to enzymes ?",o:["Holoenzyme = Coenzyme + Co-factor","Apoenzyme = Holoenzyme + Coenzymes","Holoenzyme = Apoenzyme + Coenzyme","Coenzyme = Apoenzyme + Holoenzyme"],c:2,s:`The protein part of an enzyme is the apoenzyme.
The non-protein part is the cofactor (a coenzyme is an organic cofactor).
Apoenzyme plus cofactor gives the active holoenzyme.`,sub:"Botany",ch:"Biomolecules (Biology)"},{id:"neet-2017-q059",pn:59,y:"NEET 2017 \xB7 7 May",tp:"Biomolecules (Biology)",st:"Macromolecules",q:"Which of the following are not polymeric ?",o:["Lipids","Nucleic acids","Proteins","Polysaccharides"],c:0,s:`Proteins (amino acids), nucleic acids (nucleotides) and polysaccharides (monosaccharides) are chains of repeating units.
Lipids are not chains of repeating units and have low molecular weight (below about 800 Da).
So lipids are not polymeric.`,sub:"Botany",ch:"Biomolecules (Biology)"},{id:"neet-2017-q060",pn:60,y:"NEET 2017 \xB7 7 May",tp:"Biological Classification",st:"Bacterial cell envelope",q:"Which of the following components provides sticky character to the bacterial cells ?",o:["Gylcocalyx","Cell wall","Nuclear membrane","Plasma membrane"],c:0,s:`The glycocalyx is the outermost layer of the bacterial envelope.
It is a slime layer or a thicker capsule of sticky polysaccharide.
It helps cells stick to surfaces. Bacteria have no nuclear membrane.`,sub:"Botany",ch:"Biological Classification"},{id:"neet-2017-q061",pn:61,y:"NEET 2017 \xB7 7 May",tp:"Plant Kingdom",st:"Algae: colonial forms",q:"An example of colonial alga is :",o:["Spirogyra","Chlorella","Volvox","Ulothrix"],c:2,s:`Volvox lives as a spherical colony of cells (a coenobium).
Spirogyra and Ulothrix are filamentous.
Chlorella is a single-celled alga.`,sub:"Botany",ch:"Plant Kingdom"},{id:"neet-2017-q062",pn:62,y:"NEET 2017 \xB7 7 May",tp:"Sexual Reproduction in Flowering Plants",st:"Pollination types",q:"A dioecious flowering plant prevents both :",o:["Cleistogamy and xenogamy","Autogamy and xenogamy","Autogamy and geitonogamy","Geitonogamy and xenogamy"],c:2,s:`In a dioecious plant, male and female flowers are on different plants.
Autogamy needs pollen from the same flower and geitonogamy needs pollen from another flower of the same plant.
Neither is possible, so both are prevented.
Xenogamy (between different plants) still occurs.`,sub:"Botany",ch:"Sexual Reproduction in Flowering Plants"},{id:"neet-2017-q063",pn:63,y:"NEET 2017 \xB7 7 May",tp:"Organisms and Populations",st:"Plant adaptations",q:"Plants which produce characteristic pneumatophores and show vivipary belong to :",o:["Hydrophytes","Mesophytes","Halophytes","Psammophytes"],c:2,s:`Mangrove plants grow in salty, waterlogged soil (halophytes).
They make pneumatophores (breathing roots) to get oxygen.
Their seeds germinate inside the fruit on the plant (vivipary).`,sub:"Botany",ch:"Organisms and Populations"},{id:"neet-2017-q064",pn:64,y:"NEET 2017 \xB7 7 May",tp:"Morphology of Flowering Plants",st:"Fruits",q:"Coconut fruit is",o:["Capsule","Drupe","Berry","Nut"],c:1,s:`Coconut is a one-seeded fruit with an outer fibrous mesocarp and a hard stony endocarp.
This kind of fruit is a drupe.`,sub:"Botany",ch:"Morphology of Flowering Plants"},{id:"neet-2017-q065",pn:65,y:"NEET 2017 \xB7 7 May",tp:"Anatomy of Flowering Plants",st:"Dead tissues",q:"Which of the following is made up of dead cells ?",o:["Phloem","Xylem parenchyma","Collenchyma","Phellem"],c:3,s:`Phellem (cork) cells are filled with suberin and have no protoplasm, so they are dead.
Phloem, xylem parenchyma and collenchyma are living.`,sub:"Botany",ch:"Anatomy of Flowering Plants"},{id:"neet-2017-q066",pn:66,y:"NEET 2017 \xB7 7 May",tp:"Morphology of Flowering Plants",st:"Root regions",q:"Root hairs develop from the region of :",o:["Meristematic activity","Maturation","Elongation","Root cap"],c:1,s:`Root hairs form from epidermal cells in the region of maturation.
They increase the surface for absorption of water and minerals.`,sub:"Botany",ch:"Morphology of Flowering Plants"},{id:"neet-2017-q067",pn:67,y:"NEET 2017 \xB7 7 May",tp:"Digestion and Absorption",st:"Pancreatic juice",q:"Which of the following options best represents the enzyme composition of pancreatic juice ?",o:["Lipase, amylase, trypsinogen, procarboxypeptidase","Amylase, peptidase, trypsinogen, rennin","Amylase, pepsin, trypsinogen, maltase","Peptidase, amylase, pepsin, rennin"],c:0,s:`Pancreatic juice contains inactive trypsinogen, chymotrypsinogen, procarboxypeptidase, and also amylase, lipase and nucleases.
Pepsin and rennin come from the stomach and maltase from the intestinal juice.`,sub:"Zoology",ch:"Digestion and Absorption"},{id:"neet-2017-q068",pn:68,y:"NEET 2017 \xB7 7 May",tp:"Plant Kingdom",st:"Life cycle patterns",q:"Zygotic meiosis is characteristic of :",o:["Chlamydomonas","Marchentia","Fucus","Funaria"],c:0,s:`In zygotic meiosis the zygote divides by meiosis and the adult is haploid (haplontic cycle).
Chlamydomonas is haplontic.
Marchantia and Funaria are haplo-diplontic, and Fucus is diplontic; all have sporic meiosis.`,sub:"Botany",ch:"Plant Kingdom"},{id:"neet-2017-q069",pn:69,y:"NEET 2017 \xB7 7 May",tp:"Biological Classification",st:"Archaebacteria",q:"Which of the following are found is extreme saline conditions ?",o:["Mycobacteria","Archaebacteria","Eubacteria","Cyanobacteria"],c:1,s:`Archaebacteria live in extreme habitats.
The halophiles are archaebacteria that live in very salty places.`,sub:"Botany",ch:"Biological Classification"},{id:"neet-2017-q070",pn:70,y:"NEET 2017 \xB7 7 May",tp:"Morphology of Flowering Plants",st:"Stem modifications",q:"In Bougainvillea thorns are the modifications of :",o:["Leaf","Stipules","Adventitious root","Stem"],c:3,s:`Thorns of Bougainvillea and Citrus arise from axillary buds.
So they are modified stems.`,sub:"Botany",ch:"Morphology of Flowering Plants"},{id:"neet-2017-q071",pn:71,y:"NEET 2017 \xB7 7 May",tp:"Biological Classification",st:"Viruses and viroids",q:"Viroids differ from viruses in having",o:["RNA molecules without protein coat","DNA molecules with protein coat","DNA molecules without protein coat","RNA molecules with protein coat"],c:0,s:`Viroids are free low molecular weight RNA with no protein coat.
Viruses have a protein coat around their nucleic acid.`,sub:"Botany",ch:"Biological Classification"},{id:"neet-2017-q072",pn:72,y:"NEET 2017 \xB7 7 May",tp:"Body Fluids and Circulation",st:"Blood cells",q:`Adult human RBCs are enucleate. Which of the following statements(s) is / are most appropriate explanation for this feature ?
(a) They do not need to reproduce
(b) They are somatic cells
(c) They do not metabolize
(d) All their internal space is available for oxygen transport`,o:["(b) and (c)","Only (d)","Only (a)","(a), (c) and (d)"],c:1,s:`Mature RBCs lose their nucleus so that more space is free for haemoglobin.
This helps them carry more oxygen.
Statement (b) is true but is not an explanation, and (c) is wrong because RBCs do metabolise (anaerobic respiration).
So only (d) is the explanation.`,sub:"Zoology",ch:"Body Fluids and Circulation"},{id:"neet-2017-q073",pn:73,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"Types of RNA",q:"Which of the following RNAs should be most abundant in animal cell ?",o:["mi-RNA","r-RNA","t-RNA","m-RNA"],c:1,s:`rRNA makes up about 80% of the total RNA of a cell.
tRNA is about 15% and mRNA only about 3-5%.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q074",pn:74,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"DNA replication",q:"During DNA replication, Okazaki fragments are used to elongate.",o:["The lagging strand away from the replication fork","The leading strand towards replication fork","The lagging strand towards replication fork","The leading strand away from replication"],c:0,s:`DNA polymerase adds nucleotides only in the 5' to 3' direction.
The lagging strand is made in short pieces (Okazaki fragments) that are joined later.
It is built in the direction away from the replication fork.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q075",pn:75,y:"NEET 2017 \xB7 7 May",tp:"Structural Organisation in Animals",st:"Frog male reproductive system",q:"Select the correct route for the passage of sperms in male frogs :",o:["Testes \u2192 Vasa efferentia \u2192 Kidney \u2192 Bidder's canal \u2192 Urinogenital duct \u2192 Cloaca","Testes \u2192 Bidder's canal \u2192 Kidney \u2192 Vasa efferentia \u2192 Urinogenital duct \u2192 Cloaca","Testes \u2192 Vasa efferentia \u2192 Kidney \u2192 Seminal vesicle \u2192 Urinogenital duct \u2192 Cloaca","Testes \u2192 Vasa efferentia \u2192 Bidder's canal \u2192 Ureter \u2192 Cloaca"],c:0,s:`About 10-12 vasa efferentia leave the testes and enter the kidney.
They open into Bidder's canal.
Bidder's canal joins the urinogenital duct (the ureter), which opens into the cloaca.`,sub:"Zoology",ch:"Structural Organisation in Animals"},{id:"neet-2017-q076",pn:76,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"Frame-shift mutation",q:"If there are 999 bases in an RNA that codes for a protein with 333 amino acids, and the base at position 901 is deleted such that the length of the RNA becomes 998 bases, how many codons will be altered ?",o:["333","1","11","33"],c:3,s:`999 bases make 333 codons of 3 bases each.
The first 900 bases make codons 1 to 300, which are unchanged.
Deleting base 901 shifts the reading frame (frame-shift) for everything after it.
So codons 301 to 333 are altered: 333 \u2212 300 = 33 codons.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q077",pn:77,y:"NEET 2017 \xB7 7 May",tp:"Transport in Plants",st:"Stomatal opening",q:"Which of the following facilitates opening of stomatal aperture ?",o:["Longitudinal orientation of cellulose microfibrils in the cell wall of guard cells","Contraction of outer wall of guard cells","Decrease in turgidity of guard cells","Radial orientation of cellulose microfibrils in the cell wall of guard cells"],c:3,s:`In guard cells the cellulose microfibrils are arranged radially, so the cell can only lengthen and not widen.
When guard cells become turgid, the thin outer wall bulges outward and pulls the inner wall, which opens the pore.
Lower turgidity closes the stoma.`,sub:"Botany",ch:"Transport in Plants"},{id:"neet-2017-q078",pn:78,y:"NEET 2017 \xB7 7 May",tp:"Cell Cycle and Cell Division",st:"Anaphase promoting complex",q:"Anaphase Promoting Complex (APC) is protein degradation machinery necessary for proper mitosis of animal cells. If APC is defective in a human cell, which of the following is expected to occur ?",o:["Recombination of chromosome arms will occur","Chromosomes will not condense","Chromosomes will be fragmented","Chromosomes will not segregate"],c:3,s:`APC leads to degradation of securin, which frees separase.
Separase cuts the cohesin that holds sister chromatids together.
If APC is defective, the chromatids stay joined and chromosomes do not segregate.`,sub:"Botany",ch:"Cell Cycle and Cell Division"},{id:"neet-2017-q079",pn:79,y:"NEET 2017 \xB7 7 May",tp:"Plant Kingdom",st:"Life cycle patterns",q:"Life cycle of Ectocarpus and Fucus respectively are :",o:["Haplodiplontic, Haplontic","Haplontic, Diplontic","Diplontic, Haplodiplontic","Haplodiplontic, Diplontic"],c:3,s:`Ectocarpus (a brown alga) has both a haploid and a diploid body: haplodiplontic.
Fucus has a diploid body, and only gametes are haploid: diplontic.`,sub:"Botany",ch:"Plant Kingdom"},{id:"neet-2017-q080",pn:80,y:"NEET 2017 \xB7 7 May",tp:"Respiration in Plants",st:"Krebs cycle",q:"Which statements is wrong for Krebs' cycle?",o:["The cycle starts with condensation of acetyl group (acetylCoA) with pyruvic acid to yield citric acid.","There are three points in the cycle where NAD\u207A is reduced to NADH + H\u207A","There is one point in the cycle where FAD\u207A is reduced to FADH2","During conversion of succinyl CoA to succinic acid, a molecule of GTP is synthesised"],c:0,s:`The cycle starts when acetyl CoA condenses with oxaloacetic acid (not pyruvic acid) to give citric acid.
So statement 1 is wrong.
The other three are correct: three NADH steps, one FADH2 step, and GTP formed at the succinyl CoA step.`,sub:"Botany",ch:"Respiration in Plants"},{id:"neet-2017-q081",pn:81,y:"NEET 2017 \xB7 7 May",tp:"Human Health and Disease",st:"Immunity and transplant rejection",q:"Transplantation of tissues/ organs fails often due to non-acceptance by the patient's body. Which type of immune-response is responsible for such rejections?",o:["Physiological immune response","Autoimmune response","Cell-mediated immune response","Hormonal immune response"],c:2,s:`The body recognises a graft as foreign.
This is attacked by T-lymphocytes, so graft rejection is a cell-mediated immune response.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Human Health and Disease"},{id:"neet-2017-q082",pn:82,y:"NEET 2017 \xB7 7 May",tp:"Evolution",st:"Natural selection types",q:"Artificial selection to obtain cows yielding higher milk output represents :",o:["stabilizing followed by disruptive as it stabilizes the population to produce higher yielding cows.","stabilizing selection as it stabilizes this character in the population.","directional as it pushes the mean of the character in one direction.","disruptive as it splits the population into two, one yielding higher output and the other lower output."],c:1,s:`Selecting only high-milk cows for breeding pushes the mean of the character in one direction.
That is directional selection, which is option (3).
The printed key is option (2); I keep it as printed.
Note: printed answer 2; my working gives 3 because selecting only high-yielding cows shifts the mean in one direction, which is directional selection.`,sub:"Zoology",ch:"Evolution"},{id:"neet-2017-q083",pn:83,y:"NEET 2017 \xB7 7 May",tp:"Mineral Nutrition",st:"Nitrogen fixers",q:"Select the mismatch :",o:["Rhizobium - Alfalfa","Frania - Alnus","Rhodospirillum - Mycorrhiza","Anabaena - Nitrogen fixer"],c:2,s:`Rhizobium lives in root nodules of legumes such as alfalfa.
Frankia forms nodules on Alnus.
Anabaena fixes nitrogen.
Rhodospirillum is a free-living nitrogen fixer, not a mycorrhiza, so this pair is the mismatch.`,sub:"Botany",ch:"Mineral Nutrition"},{id:"neet-2017-q084",pn:84,y:"NEET 2017 \xB7 7 May",tp:"Ecosystem",st:"Stratification",q:"Presence of plants arranged into well defined vertical layers depending on their height can be seen best in :",o:["Temperate Forest","Tropical Savannah","Tropical Rain Forest","Grassland"],c:2,s:`Tropical rain forests have many tall trees, shrubs, herbs and climbers.
They show clear vertical stratification, more than the other options.`,sub:"Botany",ch:"Ecosystem"},{id:"neet-2017-q085",pn:85,y:"NEET 2017 \xB7 7 May",tp:"Human Health and Disease",st:"Sexually transmitted diseases",q:`Match the following sexually transmitted diseases (Column \u2013 I) with their causative agent (Column \u2013 II) and select the correct option.
Column I: (a) Gonorrhea (b) Syphilis (c) Genital Warts (d) AIDS
Column II: (i) HIV (ii) Neisseria (iii) Treponema (iv) Human papilloma-virus
Options (a)(b)(c)(d):`,o:["(iv), (iii), (ii), (i)","(ii), (iii), (iv), (i)","(iii), (iv), (i), (ii)","(iv), (ii), (iii), (i)"],c:1,s:`Gonorrhea is caused by the bacterium Neisseria: (a)-(ii).
Syphilis is caused by Treponema: (b)-(iii).
Genital warts are caused by the human papilloma virus: (c)-(iv).
AIDS is caused by HIV: (d)-(i).
This is option (2).
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Human Health and Disease"},{id:"neet-2017-q086",pn:86,y:"NEET 2017 \xB7 7 May",tp:"Plant Kingdom",st:"Sporophyte features",q:"Select the mismatch :",o:["Equisetum - Homosporous","Pinus - Dioecious","Cycas - Dioecious","Salvinia - Heterosporous"],c:1,s:`Pinus bears male and female cones on the same plant, so it is monoecious, not dioecious.
Cycas has male and female cones on separate plants.
Equisetum is homosporous and Salvinia is heterosporous.`,sub:"Botany",ch:"Plant Kingdom"},{id:"neet-2017-q087",pn:87,y:"NEET 2017 \xB7 7 May",tp:"Biodiversity and Conservation",st:"Biosphere reserves",q:"The region of Biosphere Reserve which is legally protected and where no human activity is allowed is known as :",o:["Restoration zone","Core zone","Buffer zone","Transition zone"],c:1,s:`A biosphere reserve has a core zone, a buffer zone and a transition zone.
The core zone is legally protected and undisturbed, with no human activity.`,sub:"Botany",ch:"Biodiversity and Conservation"},{id:"neet-2017-q088",pn:88,y:"NEET 2017 \xB7 7 May",tp:"Anatomy of Flowering Plants",st:"Secondary growth: heartwood",q:"Identify the wrong statement in context of heartwood :",o:["It comprises dead elements with highly lignified walls","Organic compounds are deposited in it","It is highly durable.","It conducts water and minerals efficiently"],c:3,s:`Heartwood is the old central wood. Its elements are dead and lignified, filled with tannins, resins and other organic compounds, and it is durable.
It no longer conducts water; sapwood does that.
So statement 4 is wrong.`,sub:"Botany",ch:"Anatomy of Flowering Plants"},{id:"neet-2017-q089",pn:89,y:"NEET 2017 \xB7 7 May",tp:"Reproductive Health",st:"Contraceptive methods",q:"The function of copper ions in copper releasing IUD's is :",o:["They inhibit ovulation","They suppress sperm motility and fertilising capacity of sperms.","They inhibit gametogenesis.","They make uterus unsuitable for implantation"],c:1,s:`Cu ions released by the IUD reduce sperm motility and their ability to fertilise the egg.
They do not stop ovulation or gamete formation.
Uterine unsuitability for implantation is the action of hormone-releasing IUDs.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Reproductive Health"},{id:"neet-2017-q090",pn:90,y:"NEET 2017 \xB7 7 May",tp:"Biotechnology: Principles and Processes",st:"Downstream processing",q:"The process of separation and purification of expressed protein before marketing is called :",o:["Postproduction processing","Upstream processing","Downstream processing","Bioprocessing"],c:2,s:`After the product is made in the bioreactor, it is separated and purified, and tested for quality.
These steps together are downstream processing.
Note: The paper prints no solution; this working is added here.`,sub:"Botany",ch:"Biotechnology: Principles and Processes"},{id:"neet-2017-q091",pn:91,y:"NEET 2017 \xB7 7 May",tp:"Biological Classification",st:"Mycoplasma",q:"Which among the following are the smallest living cells, known without a definite cell wall, pathogenic to plants as well as animals and can survive without oxygen ?",o:["Nostoc","Bacillus","Pseudomonas","Mycoplasma"],c:3,s:`Mycoplasmas are the smallest living cells and have no cell wall.
They can live without oxygen and cause disease in plants and animals.
Nostoc, Bacillus and Pseudomonas have cell walls.`,sub:"Botany",ch:"Biological Classification"},{id:"neet-2017-q092",pn:92,y:"NEET 2017 \xB7 7 May",tp:"Photosynthesis in Higher Plants",st:"C4 pathway",q:"Phosphoenol pyruvate (PEP) is the primary CO2 acceptor in :",o:["C3 and C4 plants","C3 plants","C4 plants","C2 plants"],c:2,s:`In C4 plants, CO2 is first fixed in mesophyll cells by PEP carboxylase, with PEP as the acceptor.
C3 plants use RuBP as the CO2 acceptor.`,sub:"Botany",ch:"Photosynthesis in Higher Plants"},{id:"neet-2017-q093",pn:93,y:"NEET 2017 \xB7 7 May",tp:"Human Health and Disease",st:"Lymphoid tissues",q:"MALT constitutes about ________ percent of the lymphoid tissue in human body.",o:["10%","50%","20%","70%"],c:1,s:`MALT (mucosa-associated lymphoid tissue) lies in the lining of respiratory, digestive and urogenital tracts.
It makes up about 50 percent of the lymphoid tissue of the body.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Human Health and Disease"},{id:"neet-2017-q094",pn:94,y:"NEET 2017 \xB7 7 May",tp:"Biotechnology: Principles and Processes",st:"Gel electrophoresis",q:"The DNA fragments separated on an agarose gel can be visualised after staining with :",o:["Ethidium bromide","Bromophenol blue","Acetocarmine","Aniline blue"],c:0,s:`Ethidium bromide binds DNA and glows orange under UV light.
So the DNA bands become visible.
Bromophenol blue is only a tracking dye in the loading buffer.
Note: The paper prints no solution; this working is added here.`,sub:"Botany",ch:"Biotechnology: Principles and Processes"},{id:"neet-2017-q095",pn:95,y:"NEET 2017 \xB7 7 May",tp:"Human Reproduction",st:"Fertilisation",q:"Capacitation occurs in :",o:["Female Reproductive tract","Rete testis","Epididymis","Vas deferens"],c:0,s:`Freshly ejaculated sperm cannot fertilise an egg.
They gain this ability (capacitation) after staying in the female reproductive tract.`,sub:"Zoology",ch:"Human Reproduction"},{id:"neet-2017-q096",pn:96,y:"NEET 2017 \xB7 7 May",tp:"Microbes in Human Welfare",st:"Microbes and products",q:"Which of the following is correctly matched for the product produced by them ?",o:["Sacchromyces cerevisiae : Ethanol","Acetobacter aceti : Antibiotics","Methanobacterium : Lactic acid","Penicillium notatum : Acetic acid"],c:0,s:`Yeast (Saccharomyces cerevisiae) ferments sugar to ethanol.
Acetobacter aceti makes acetic acid, Methanobacterium makes methane, and Penicillium notatum makes penicillin.
So only the first pair is correct.`,sub:"Botany",ch:"Microbes in Human Welfare"},{id:"neet-2017-q097",pn:97,y:"NEET 2017 \xB7 7 May",tp:"Excretory Products and their Elimination",st:"Loop of Henle",q:"Which of the following statements is correct?",o:["The descending limb of loop of Henle is permeable to electrolytes.","The ascending limb of loop of Henle is impermeable to water.","The descending limb of loop of Henle is impermeable to water.","The ascending limb of loop of Henle is permeable to water."],c:1,s:`The descending limb is permeable to water and almost impermeable to electrolytes.
The ascending limb is impermeable to water but lets electrolytes pass.
So only statement 2 is correct.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Excretory Products and their Elimination"},{id:"neet-2017-q098",pn:98,y:"NEET 2017 \xB7 7 May",tp:"Transport in Plants",st:"Water potential",q:"The water potential of pure water is :",o:["More than one","Zero","Less than zero","More than zero but less than one"],c:1,s:`Water potential is the free energy of water.
It is highest for pure water at standard conditions and is taken as zero.
Adding solute makes it negative.`,sub:"Botany",ch:"Transport in Plants"},{id:"neet-2017-q099",pn:99,y:"NEET 2017 \xB7 7 May",tp:"Principles of Inheritance and Variation",st:"Blood group inheritance",q:"The genotypes of a Husband and Wife are I\u1D2CI\u1D2E and I\u1D2Ci. Among the blood types of their children, how many different genotypes and phenotypes are possible?",o:["4 genotypes ; 4 phenotypes","3 genotypes ; 3 phenotypes","3 genotypes ; 4 phenotypes","4 genotypes ; 3 phenotypes"],c:3,s:`Gametes of I\u1D2CI\u1D2E: I\u1D2C, I\u1D2E. Gametes of I\u1D2Ci: I\u1D2C, i.
Children: I\u1D2CI\u1D2C, I\u1D2Ci, I\u1D2CI\u1D2E, I\u1D2Ei, which is 4 genotypes.
Phenotypes: I\u1D2CI\u1D2C and I\u1D2Ci are A, I\u1D2CI\u1D2E is AB, I\u1D2Ei is B, so 3 phenotypes.`,sub:"Zoology",ch:"Principles of Inheritance and Variation"},{id:"neet-2017-q100",pn:100,y:"NEET 2017 \xB7 7 May",tp:"Animal Kingdom",st:"Hemichordata",q:"An important characteristic that Hemichordates share with Chordates is :",o:["pharynx without gill slits","absence of notochord","ventral tubular nerve cord","pharynx with gill slits"],c:3,s:`Hemichordates have gill slits in the pharynx, as chordates do.
They have no true notochord, and their nerve cord is not the dorsal tubular type of chordates.
So the shared feature is pharyngeal gill slits.`,sub:"Zoology",ch:"Animal Kingdom"},{id:"neet-2017-q101",pn:101,y:"NEET 2017 \xB7 7 May",tp:"Biodiversity and Conservation",st:"Ex-situ conservation",q:"Which one of the following is related to Ex-situ conservation of threatened animals and plants ?",o:["Himalayan region","Wildlife Safari Parks","Biodiversity hot spots","Amazon rainforest"],c:1,s:`Ex-situ conservation means protecting species outside their natural habitat, such as in zoos, botanical gardens and safari parks.
The Himalayas, hot spots and the Amazon rainforest are natural habitats (in-situ).
So wildlife safari parks is the answer.`,sub:"Botany",ch:"Biodiversity and Conservation"},{id:"neet-2017-q102",pn:102,y:"NEET 2017 \xB7 7 May",tp:"Microbes in Human Welfare",st:"Sewage treatment",q:"Which of the following in sewage treatment removes suspended solids ?",o:["Sludge treatment","Tertiary treatment","Secondary treatment","Primary treatment"],c:3,s:`Primary treatment is physical: filtration and sedimentation.
It removes floating and suspended solids.
Secondary treatment is biological and removes organic matter.`,sub:"Botany",ch:"Microbes in Human Welfare"},{id:"neet-2017-q103",pn:103,y:"NEET 2017 \xB7 7 May",tp:"Locomotion and Movement",st:"Human rib cage",q:"Out of \u2018X\u2019 pairs of ribs in humans only \u2018Y\u2019 pairs are true ribs. Select the option that correctly represents values of X and Y and provides their explanation :",o:["X = 24, Y = 12. True ribs are dorsally attached to vertebral column but are free on ventral side.","X = 12, Y = 7. True ribs are attached dorsally to vertebral column and ventrally to the sternum.","X = 12, Y = 5. True ribs are attached dorsally to vertebral column and sternum on the two ends.","X = 24, Y = 7. True ribs are dorsally attached to vertebral column but are free on ventral side."],c:1,s:`Humans have 12 pairs of ribs.
The first 7 pairs are true ribs: they join the thoracic vertebrae at the back and the sternum in front (through costal cartilage).
So X = 12, Y = 7 with the explanation in option 2.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Locomotion and Movement"},{id:"neet-2017-q104",pn:104,y:"NEET 2017 \xB7 7 May",tp:"Sexual Reproduction in Flowering Plants",st:"Double fertilisation",q:"Double fertilization is exhibited by :",o:["Angiosperms","Gymnosperms","Algae","Fungi"],c:0,s:`In double fertilisation one male gamete fuses with the egg and another with the two polar nuclei (triple fusion).
This happens only in angiosperms.`,sub:"Botany",ch:"Sexual Reproduction in Flowering Plants"},{id:"neet-2017-q105",pn:105,y:"NEET 2017 \xB7 7 May",tp:"Sexual Reproduction in Flowering Plants",st:"Pollination agents",q:"Attractants and rewards are required for :",o:["Cleistogamy","Anemophily","Entomophily","Hydrophily"],c:2,s:`Insect-pollinated flowers need colour, scent and nectar or pollen as rewards to attract insects.
Wind- and water-pollinated flowers do not need them, and cleistogamous flowers never open.`,sub:"Botany",ch:"Sexual Reproduction in Flowering Plants"},{id:"neet-2017-q106",pn:106,y:"NEET 2017 \xB7 7 May",tp:"Principles of Inheritance and Variation",st:"Mendel's work",q:"Which one from those given below is the period for Mendel\u2019s hybridization experiments ?",o:["1870 \u2013 1877","1856 \u2013 1863","1840 \u2013 1850","1857 \u2013 1869"],c:1,s:`Mendel carried out his pea hybridisation experiments from 1856 to 1863.
He published his results in 1865.
Note: The paper prints no solution; this working is added here.`,sub:"Botany",ch:"Principles of Inheritance and Variation"},{id:"neet-2017-q107",pn:107,y:"NEET 2017 \xB7 7 May",tp:"Neural Control and Coordination",st:"Synapse",q:"Receptor sites for neurotransmitters are present on",o:["post-synaptic membrane","membranes of synaptic vesicles","pre-synaptic membrane","tips of axons"],c:0,s:`Neurotransmitters are released from synaptic vesicles of the pre-synaptic neuron into the cleft.
They bind to receptors on the post-synaptic membrane.`,sub:"Zoology",ch:"Neural Control and Coordination"},{id:"neet-2017-q108",pn:108,y:"NEET 2017 \xB7 7 May",tp:"Animal Kingdom",st:"Mammals",q:"Which among these is the correct combination of aquatic mammals ?",o:["Trygon, Whales, Seals","Seals, Dolphins, Sharks","Dolphins, Seals, Trygon","Whales, Dolphins, Seals"],c:3,s:`Trygon (sting ray) and sharks are fishes.
Whales, dolphins and seals are mammals that live in water.`,sub:"Zoology",ch:"Animal Kingdom"},{id:"neet-2017-q109",pn:109,y:"NEET 2017 \xB7 7 May",tp:"Neural Control and Coordination",st:"Vision",q:`Good vision depends on adequate intake of carotene rich food. Select the best option from the following statements.
(a) Vitamin A derivatives are formed from carotene.
(b) The photopigments are embedded in the membrane discs of the inner segment
(c) Retinal is derivative of Vitamin A
(d) Retinal is a light absorbing part of all the visual photopigments`,o:["(b), (c) and (d)","(a) and (b)","(a), (c) and (d)","(a) and (c)"],c:2,s:`Carotene is the precursor of vitamin A, so (a) is correct.
Retinal is made from vitamin A and is the light-absorbing part of all visual pigments, so (c) and (d) are correct.
Photopigments lie in the membrane discs of the outer segment, not the inner segment, so (b) is wrong.`,sub:"Zoology",ch:"Neural Control and Coordination"},{id:"neet-2017-q110",pn:110,y:"NEET 2017 \xB7 7 May",tp:"Biotechnology: Principles and Processes",st:"Gel electrophoresis",q:"What is the criterion for DNA fragments movement on agarose gel during gel electrophoresis ?",o:["Negatively charged fragments do not move","The larger the fragment size, the farther it moves","The smaller the fragment size, the farther it moves","Positively charged fragment move to farther end"],c:2,s:`DNA is negatively charged and moves toward the positive electrode.
The agarose gel acts like a sieve.
Small fragments pass through easily and move farther than large ones.
Note: The paper prints no solution; this working is added here.`,sub:"Botany",ch:"Biotechnology: Principles and Processes"},{id:"neet-2017-q111",pn:111,y:"NEET 2017 \xB7 7 May",tp:"Chemical Coordination and Integration",st:"Growth hormone",q:"Hypersecretion of Grwoth Hormone in adults does not cause further increase in height, because :",o:["Muscle fibres do not grow in size after birth","Growth Hormone becomes inactive in adults","Epiphyseal plates close after adolescence","Bones loose their sensitivity to Growth Hormone in adults"],c:2,s:`Bones grow in length at the epiphyseal (growth) plates.
These plates close after adolescence.
So extra growth hormone in adults cannot make them taller.`,sub:"Zoology",ch:"Chemical Coordination and Integration"},{id:"neet-2017-q112",pn:112,y:"NEET 2017 \xB7 7 May",tp:"Animal Kingdom",st:"Classification of mammals",q:"Which of the following represents order of \u2018Horse\u2019 ?",o:["Ferus","Equidae","Perissodactyla","Caballus"],c:2,s:`Horse is Equus caballus.
Caballus is the species, Equus the genus and Equidae the family.
The order is Perissodactyla (odd-toed mammals).`,sub:"Zoology",ch:"Animal Kingdom"},{id:"neet-2017-q113",pn:113,y:"NEET 2017 \xB7 7 May",tp:"Principles of Inheritance and Variation",st:"Genetic disorders",q:"Thalassemia and sickle cell anemia are caused due to a problem in globin molecule synthesis. Select the correct statement.",o:["Sickle cell anemia is due to a quantitative problem of globin molecules","Both are due to a qualitative defect in globin chain synthesis","Both are due to a quantitative defect in globin chain synthesis","Thalassemia is due to less synthesis of globin molecules"],c:3,s:`Thalassemia is a quantitative defect: too little of a globin chain is made.
Sickle cell anaemia is a qualitative defect: the chain is made but has a changed amino acid (Glu replaced by Val).
So only statement 4 is correct.`,sub:"Zoology",ch:"Principles of Inheritance and Variation"},{id:"neet-2017-q114",pn:114,y:"NEET 2017 \xB7 7 May",tp:"Neural Control and Coordination",st:"Neuroglia",q:"Myelin sheath is produced by :",o:["Osteoclasts and Astrocytes","Schwann Cells and Oligodendrocytes","Astrocytes and Schwann Cells","Oligodendrocytes and Osteoclasts"],c:1,s:`Schwann cells make the myelin sheath in the peripheral nervous system.
Oligodendrocytes make it in the central nervous system.
Osteoclasts are bone cells and astrocytes do not make myelin.`,sub:"Zoology",ch:"Neural Control and Coordination"},{id:"neet-2017-q115",pn:115,y:"NEET 2017 \xB7 7 May",tp:"Microbes in Human Welfare",st:"Animal breeding",q:"Homozygous purelines in cattle can be obtained by :",o:["mating of individuals of different species","mating of related individuals of same breed","mating of unrelated individuals of same breed","mating of individuals of different breed"],c:1,s:`Inbreeding (mating of closely related animals of the same breed) increases homozygosity.
So it is used to produce pure lines.
Crossing unrelated or different breeds does the opposite.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Microbes in Human Welfare"},{id:"neet-2017-q116",pn:116,y:"NEET 2017 \xB7 7 May",tp:"Organisms and Populations",st:"Population interactions",q:"Mycorrhizae are the example of :",o:["Mutualism","Fungistasis","Amensalism","Antibiosis"],c:0,s:`Mycorrhiza is an association of a fungus and plant roots.
The fungus helps absorb water and minerals and the plant gives food.
Both benefit, so this is mutualism.`,sub:"Botany",ch:"Organisms and Populations"},{id:"neet-2017-q117",pn:117,y:"NEET 2017 \xB7 7 May",tp:"Digestion and Absorption",st:"Human dentition",q:"A baby boy aged two years is admitted to play school and passes through a dental check-up. The dentist observed that the boy had twenty teeth. Which teeth were absent ?",o:["Molars","Incisors","Canines","Pre-molars"],c:3,s:`The milk (deciduous) dental formula is I 2/2, C 1/1, PM 0/0, M 2/2 on each side, giving 20 teeth.
So pre-molars are absent in milk teeth.`,sub:"Zoology",ch:"Digestion and Absorption"},{id:"neet-2017-q118",pn:118,y:"NEET 2017 \xB7 7 May",tp:"Principles of Inheritance and Variation",st:"Mendel's pea characters",q:"Among the following characters, which one was not considered by Mendel in his experiments on pea ?",o:["Pod-Inflated or Constricted","Stem-Tall or Dwarf","Trichomes-Glandular or non-glandular","Seed-Green or Yellow"],c:2,s:`Mendel studied seven pairs of traits: stem height, flower colour, flower position, pod shape (inflated or constricted), pod colour, seed shape and seed colour.
Glandular or non-glandular trichomes was not one of them.
Note: The paper prints no solution; this working is added here.`,sub:"Botany",ch:"Principles of Inheritance and Variation"},{id:"neet-2017-q119",pn:119,y:"NEET 2017 \xB7 7 May",tp:"Body Fluids and Circulation",st:"Hepatic portal system",q:"The hepatic portal vein drains blood to liver from :",o:["Intestine","Heart","Stomach","Kidneys"],c:0,s:`The hepatic portal vein carries nutrient-rich blood from the intestine to the liver.
The other options do not drain through it.`,sub:"Zoology",ch:"Body Fluids and Circulation"},{id:"neet-2017-q120",pn:120,y:"NEET 2017 \xB7 7 May",tp:"Digestion and Absorption",st:"Intestinal glands",q:"Which cells of \u2018Crypts of Lieberkuhn\u2019 secrete antibacterial lysozyme ?",o:["Kupffer cells","Argentaffin cells","Paneth cells","Zymogen cells"],c:2,s:`Paneth cells in the crypts of Lieberkuhn secrete lysozyme, which kills bacteria.
Kupffer cells are in the liver and zymogen cells are in the stomach.`,sub:"Zoology",ch:"Digestion and Absorption"},{id:"neet-2017-q121",pn:121,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"RNA splicing",q:"Spliceosomes are not found in cells of :",o:["Bacteria","Plants","Fungi","Animals"],c:0,s:`Spliceosomes remove introns from pre-mRNA.
Bacterial genes have no introns, so bacteria have no spliceosomes.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q122",pn:122,y:"NEET 2017 \xB7 7 May",tp:"Body Fluids and Circulation",st:"Heart: myogenic",q:`Frog\u2019s heart when taken out of the body continues to beat for sometime. Select the best option from the following statements.
(a) Frog is a poikilotherm
(b) Frog does not have any coronary circulation
(c) Heart is \u201Cmyogenic\u201D in nature
(d) Heart is autoexcitable`,o:["(c) and (d)","Only (c)","Only (d)","(a) and (b)"],c:0,s:`The heart beats without nerve signals because its own muscle can start the impulse (myogenic).
It has its own pacemaker, so it is auto-excitable.
Being cold-blooded or lacking coronary circulation does not explain beating outside the body.`,sub:"Zoology",ch:"Body Fluids and Circulation"},{id:"neet-2017-q123",pn:123,y:"NEET 2017 \xB7 7 May",tp:"Sexual Reproduction in Flowering Plants",st:"Megasporogenesis",q:"Functional megaspore in an angiosperm develops into :",o:["Embryo","Ovule","Endosperm","Embryo sac"],c:3,s:`The functional megaspore divides to form the female gametophyte.
This is the embryo sac.`,sub:"Botany",ch:"Sexual Reproduction in Flowering Plants"},{id:"neet-2017-q124",pn:124,y:"NEET 2017 \xB7 7 May",tp:"Biodiversity and Conservation",st:"Species-area relationship",q:"Alexander Von Humbolt described for the first time :",o:["Population Growth equation","Ecological Biodiversity","Laws of limiting factor","Species are relationships"],c:3,s:`Alexander von Humboldt observed that within a region, species richness increases with area.
This is the species-area relationship.`,sub:"Botany",ch:"Biodiversity and Conservation"},{id:"neet-2017-q125",pn:125,y:"NEET 2017 \xB7 7 May",tp:"Morphology of Flowering Plants",st:"Fruit and seed",q:"The morphological nature of edible part of coconut is :",o:["Pericarp","Perisperm","Cotayledon","Endosperm"],c:3,s:`The coconut water is free-nuclear endosperm and the white kernel is cellular endosperm.
Both are edible parts and are endosperm.`,sub:"Botany",ch:"Morphology of Flowering Plants"},{id:"neet-2017-q126",pn:126,y:"NEET 2017 \xB7 7 May",tp:"Chemical Coordination and Integration",st:"Endocrine glands",q:"A temporary endocrine gland in the human body is :",o:["Corpus allatum","Pineal gland","Corpus cardiacum","Corpus luteum"],c:3,s:`Corpus luteum forms from the Graafian follicle after ovulation and secretes progesterone.
It breaks down if no pregnancy occurs, so it is temporary.
Corpus allatum and corpus cardiacum are in insects.`,sub:"Zoology",ch:"Chemical Coordination and Integration"},{id:"neet-2017-q127",pn:127,y:"NEET 2017 \xB7 7 May",tp:"Sexual Reproduction in Flowering Plants",st:"Pollination",q:"Flowers which have single ovule in the ovary and are packed into inflorescence are usually pollinated by :",o:["Bat","Water","Bee","Wind"],c:3,s:"Wind-pollinated flowers usually have a single ovule in the ovary and are grouped in inflorescences (such as corn cob).",sub:"Botany",ch:"Sexual Reproduction in Flowering Plants"},{id:"neet-2017-q128",pn:128,y:"NEET 2017 \xB7 7 May",tp:"Locomotion and Movement",st:"Joints",q:"The pivot joint between atlas and axis is a type of :",o:["saddle joint","fibrous joint","cartilaginous joint","synovial joint"],c:3,s:`The atlas and axis join by a pivot joint, which allows the head to rotate.
Pivot joints are a type of synovial joint.`,sub:"Zoology",ch:"Locomotion and Movement"},{id:"neet-2017-q129",pn:129,y:"NEET 2017 \xB7 7 May",tp:"Excretory Products and their Elimination",st:"Regulation of kidney function",q:"A decrease in blood pressure/volume will not cause the release of :",o:["ADH","Renin","Atrial Natriuretic Factor","Aldosterone"],c:2,s:`Low blood pressure or volume causes release of renin (which leads to aldosterone) and ADH to raise volume.
Atrial natriuretic factor is released when blood pressure rises, and it lowers pressure.
So it is not released.`,sub:"Zoology",ch:"Excretory Products and their Elimination"},{id:"neet-2017-q130",pn:130,y:"NEET 2017 \xB7 7 May",tp:"Ecosystem",st:"Biomass",q:"Which ecosystem has the maximum biomass ?",o:["Lake ecosystem","Forest ecosystem","Grassland ecosystem","Pond ecosystem"],c:1,s:"Forests have large trees, so they hold the highest biomass of the listed ecosystems.",sub:"Botany",ch:"Ecosystem"},{id:"neet-2017-q131",pn:131,y:"NEET 2017 \xB7 7 May",tp:"Principles of Inheritance and Variation",st:"Chromosomal disorders",q:"A disease caused by an autosomal primary non-disjunction is :",o:["Sickle Cell Anemia","Down's Syndrome","Klinefelter's Syndrome","Turner's Syndrome"],c:1,s:`Down's syndrome is trisomy of an autosome (chromosome 21), caused by non-disjunction.
Klinefelter's and Turner's involve sex chromosomes, and sickle cell anaemia is a gene mutation.
Note: The paper prints no solution; this working is added here.`,sub:"Zoology",ch:"Principles of Inheritance and Variation"},{id:"neet-2017-q132",pn:132,y:"NEET 2017 \xB7 7 May",tp:"Cell: The Unit of Life",st:"Cell organelles",q:"Which of the following cell organelles is responsible for extracting energy from carbohydrates to form ATP?",o:["Mitochondrion","Lysosome","Ribosome","Chloroplast"],c:0,s:`Mitochondria carry out the Krebs cycle and the electron transport chain.
This extracts energy from the breakdown of carbohydrates and makes ATP.`,sub:"Botany",ch:"Cell: The Unit of Life"},{id:"neet-2017-q133",pn:133,y:"NEET 2017 \xB7 7 May",tp:"Molecular Basis of Inheritance",st:"DNA replication in bacteria",q:"DNA replication in bacteria occurs-",o:["Just before transcription","During S phase","Within nucleolus","Prior to fission"],c:3,s:`Bacteria have no nucleus, nucleolus or defined S phase.
They copy their DNA before binary fission so each daughter cell gets a copy.`,sub:"Botany",ch:"Molecular Basis of Inheritance"},{id:"neet-2017-q134",pn:134,y:"NEET 2017 \xB7 7 May",tp:"Reproductive Health",st:"Assisted reproduction",q:"In case of a couple where the male is having a very low sperm count, which technique will be suitable for fertilization ?",o:["Intracytoplasmic sperm injection","Intrauterine transfer","Gamete intracytoplasmic fallopian transfer","Artifical Insemination"],c:3,s:`Artificial insemination (AI) collects the semen of the husband (or a donor), concentrates it, and puts it into the vagina or uterus (IUI).
This suits a low sperm count.
The printed key is option 4.
Note: The paper prints no solution; this working is added here. ICSI (option 1) also helps in male infertility; the printed key 4 is kept.`,sub:"Zoology",ch:"Reproductive Health"},{id:"neet-2017-q135",pn:135,y:"NEET 2017 \xB7 7 May",tp:"Biodiversity and Conservation",st:"Air pollution: aerosols",q:"Which one of the following statements is not valid for aerosols ?",o:["They have negative impact on agricultural land","They are harmful to human health","They alter rainfall and monsoon patterns","They cause increased agricultural productivity"],c:3,s:`Aerosols are fine particles in the air that cause smog and haze.
They harm health, reduce sunlight and crop yield, and alter rain patterns.
Increased productivity is not valid.`,sub:"Botany",ch:"Biodiversity and Conservation"},{id:"neet-2017-q136",pn:136,y:"NEET 2017 \xB7 7 May",tp:"Thermodynamics",st:"Thermodynamic processes",q:`Thermodynamic processes are indicated in the following diagram. Match the following :
Column 1: P. Process I  Q. Process II  R. Process III  S. Process IV
Column 2: a. Adiabatic  b. Isobaric  c. Isochoric  d. Isothermal`,o:["P \u2192 d, Q \u2192 b, R \u2192 a, S \u2192 c","P \u2192 a, Q \u2192 c, R \u2192 d, S \u2192 b","P \u2192 c, Q \u2192 a, R \u2192 d, S \u2192 b","P \u2192 c, Q \u2192 d, R \u2192 b, S \u2192 a"],c:2,s:`Process I is a vertical line on the P-V graph (volume constant): isochoric (c).
Process II falls steeply from one isotherm to a lower one with a change in temperature and no heat flow: adiabatic (a).
Process III stays on the same isotherm: isothermal (d).
Process IV is a horizontal line (pressure constant): isobaric (b).`,fig:{w:290,h:200,alt:"P-V graph with isotherms 300 K, 500 K and 700 K and four processes I to IV starting from one point and ending at points f.",d:[["l",30,175,30,10,"a"],["l",30,175,250,175,"a"],["t",22,16,"P","e"],["t",252,189,"V",""],["t",24,188,"O","e"],["p","M90 40 C92.5 44.5 100 59.5 105 67 C110 74.5 115 79.8 120 85 C125 90.2 130 94.2 135 97.9 C140 101.7 145 104.7 150 107.5 C155 110.3 160 112.8 165 115 C170 117.3 177.5 120 180 121"],["p","M68 56.6 C71.1 63.1 80.5 85.8 86.7 95.6 C92.9 105.4 99.1 110 105.3 115.3 C111.5 120.5 117.8 123.8 124 127.1 C130.2 130.4 136.5 132.8 142.7 135.1 C148.9 137.4 155.1 139 161.3 140.7 C167.5 142.3 176.9 144.3 180 145"],["p","M60 78.3 C63.3 84.8 73.3 107.8 80 117 C86.7 126.2 93.3 129.3 100 133.6 C106.7 137.9 113.3 140.3 120 142.8 C126.7 145.3 133.3 146.9 140 148.6 C146.7 150.3 153.3 151.5 160 152.7 C166.7 153.9 176.7 155.2 180 155.7"],["t",182,111,"700 K","s"],["t",182,142,"500 K","s"],["t",182,158,"300 K","s"],["l",80,85,80,125,"a"],["c",80,125,2,"F"],["t",74,139,"f","e"],["t",74,83,"I","e"],["l",80,85,120,85,"a"],["c",120,85,2,"F"],["t",126,81,"f",""],["t",84,77,"IV",""],["p","M80 85 C81.5 87.4 86.2 95.1 89.3 99.2 C92.4 103.3 95.6 106.5 98.7 109.5 C101.8 112.5 106.5 116 108 117.3","a"],["c",108,117.3,2,"F"],["t",113,111.3,"f",""],["t",92,97,"III",""],["p","M80 85 C83 105 90 107.5 96 129.5","a"],["c",96,129.5,2,"F"],["t",104,143.5,"f",""],["t",93,145.5,"II","e"]]},sub:"Physics",ch:"Thermodynamics"},{id:"neet-2017-q137",pn:137,y:"NEET 2017 \xB7 7 May",tp:"Work, Energy and Power",st:"Work-energy theorem",q:"Consider a drop of rain water having mass 1g falling from a height of 1 km. It hits the ground with a speed of 50 m/s. Take 'g' constant with a value 10 m/s\xB2. The work done by the (i) gravitational force and the (ii) resistive force of air is",o:["(i) 10 J (ii) \u2013 8.75 J","(i) \u201310 J (ii) \u20138.25 J","(i) 1.25 J (ii) \u20138.25 J","(i) 100 J (ii) 8.75 J"],c:0,s:`(i) Work by gravity = mgh = 1 \xD7 10\u207B\xB3 \xD7 10 \xD7 1000 = 10 J.
(ii) By the work-energy theorem, W(gravity) + W(resistive) = change in kinetic energy.
Kinetic energy gained = \xBD \xD7 10\u207B\xB3 \xD7 50\xB2 = 1.25 J.
W(resistive) = 1.25 \u2212 10 = \u22128.75 J.`,sub:"Physics",ch:"Work, Energy and Power"},{id:"neet-2017-q138",pn:138,y:"NEET 2017 \xB7 7 May",tp:"Moving Charges and Magnetism",st:"Torque and work on a coil",q:"A 250 Turn rectangular coil of length 2.1 cm and width 1.25 cm carries a current of 85 \xB5A and subjected to a magnetic field of strength 0.85 T. Work done for rotating the coil by 180\xBA against the torque is :",o:["1.15 \xB5J","9.1 \xB5J","4.55 \xB5J","2.3 \xB5J"],c:1,s:`Work to turn a coil from \u03B8 = 0\xB0 to 180\xB0 is W = MB(cos 0\xB0 \u2212 cos 180\xB0) = 2MB.
M = NIA = 250 \xD7 85\xD710\u207B\u2076 \xD7 (2.1\xD710\u207B\xB2 \xD7 1.25\xD710\u207B\xB2) = 250 \xD7 85\xD710\u207B\u2076 \xD7 2.625\xD710\u207B\u2074 A.
W = 2 \xD7 NIAB with B = 0.85 T.
The result is about 9.5 \xB5J, so the nearest option is 9.1 \xB5J.
Note: printed answer 2 (9.1 \xB5J); my working gives about 9.5 \xB5J, closest to option 2, so the key is kept.`,sub:"Physics",ch:"Moving Charges and Magnetism"},{id:"neet-2017-q139",pn:139,y:"NEET 2017 \xB7 7 May",tp:"Wave Optics",st:"Polarisation and Malus' law",q:"Two Polaroids P1 and P2 are placed with their axis perpendicular to each other. Unpolarised light I0 is incident on P1. A third polaroid P3 is kept in between P1 and P2 such that its axis makes an angle 45\xBA with that of P1. The intensity of transmitted light through P2 is",o:["I0/16","I0/2","I0/4","I0/8"],c:3,s:`Unpolarised light through P1 gives I0/2.
P3 is at 45\xB0 to P1: by Malus' law I = (I0/2) cos\xB245\xB0 = I0/4.
P2 is at 90\xB0 to P1, so it is at 45\xB0 to P3: I = (I0/4) cos\xB245\xB0 = I0/8.`,sub:"Physics",ch:"Wave Optics"},{id:"neet-2017-q140",pn:140,y:"NEET 2017 \xB7 7 May",tp:"Nuclei",st:"Radioactive decay",q:"Radioactive material 'A' has decay constant '8\u03BB' and material 'B' has decay constant '\u03BB'. Initially they have same number of nuclei. After what time, the ratio of number of nuclei of material 'B' to that 'A' will be 1/e ?",o:["1/(9\u03BB)","1/\u03BB","1/(7\u03BB)","1/(8\u03BB)"],a:"3/Bonus",s:`N_A = N0 e^(\u22128\u03BBt) and N_B = N0 e^(\u2212\u03BBt).
N_B/N_A = e^(\u2212\u03BBt)/e^(\u22128\u03BBt) = e^(7\u03BBt).
Setting this equal to 1/e gives 7\u03BBt = \u22121, so t is negative, which is impossible.
The printed key marks this question as a bonus (the ratio A to B would give t = 1/(7\u03BB), option 3).
Note: printed key is '3/Bonus'; B to A cannot be 1/e for t > 0 (it gives t = -1/(7\u03BB)); the question is a bonus, and option 3 is the value if the ratio were A to B.`,sub:"Physics",ch:"Nuclei"},{id:"neet-2017-q141",pn:141,y:"NEET 2017 \xB7 7 May",tp:"Semiconductor Electronics",st:"Logic gates",q:"The given electrical network is equivalent to",o:["NOT gate","AND gate","OR gate","NOR gate"],c:3,s:`The first gate is a NOR gate.
The second gate has both inputs joined, so it works as a NOT gate; the last gate is also a NOT gate.
Two NOT gates in series cancel, so the network is a NOR gate.`,fig:{w:370,h:90,alt:"Two input terminals A and B go to a NOR gate; its output feeds a second NOR-shaped gate with both inputs joined through a box; that output goes to a NOT gate giving output Y.",d:[["p","M56 25 Q82 25 100 45 Q82 65 56 65 Q68 45 56 25 Z"],["c",105,45,4.5],["l",109.5,45,144,45],["l",28,37,59,37],["l",28,53,59,53],["c",28,37,2.5,"F"],["c",28,53,2.5,"F"],["t",21,34,"A","e"],["t",21,58,"B","e"],["l",144,45,154,45],["r",154,36,20,18],["l",174,45,186,45],["p","M186 25 Q212 25 230 45 Q212 65 186 65 Q198 45 186 25 Z"],["c",235,45,4.5],["l",239.5,45,264,45],["p","M264 30 L264 60 L296 45 Z"],["c",300.5,45,4.5],["l",305,45,336,45],["c",336,45,2.5,"F"],["t",344,49,"Y",""]]},sub:"Physics",ch:"Semiconductor Electronics"},{id:"neet-2017-q142",pn:142,y:"NEET 2017 \xB7 7 May",tp:"Ray Optics and Optical Instruments",st:"Resolving power",q:"The ratio of resolving powers of an optical microscope for two wavelengths \u03BB1 = 4000 \xC5 and \u03BB2 = 6000 \xC5 is",o:["16 : 81","8 : 27","9 : 4","3 : 2"],c:3,s:`Resolving power of a microscope is proportional to 1/\u03BB.
RP1/RP2 = \u03BB2/\u03BB1 = 6000/4000 = 3/2.
So the ratio is 3 : 2.`,sub:"Physics",ch:"Ray Optics and Optical Instruments"},{id:"neet-2017-q143",pn:143,y:"NEET 2017 \xB7 7 May",tp:"Semiconductor Electronics",st:"Transistor amplifier",q:"In a common emitter transistor amplifier the audio signal voltage across the collector is 3 V. The resistance of collector is 3 k\u03A9. If current gain is 100 and the base resistance is 2 k\u03A9, the voltage and power gain of the amplifier is :",o:["20 and 2000","200 and 1000","15 and 200","150 and 15000"],c:3,s:`Voltage gain Av = \u03B2 \xD7 (RC/RB) = 100 \xD7 (3 k\u03A9/2 k\u03A9) = 150.
Power gain = \u03B2 \xD7 Av = 100 \xD7 150 = 15000.`,sub:"Physics",ch:"Semiconductor Electronics"},{id:"neet-2017-q144",pn:144,y:"NEET 2017 \xB7 7 May",tp:"Waves",st:"Doppler effect",q:"Two cars moving in opposite directions approach each other with speed of 22 m/s and 16.5 m/s respectively. The driver of the first car blows a horn having a frequency 400 Hz. The frequency heard by the driver of the second car is [velocity of sound 340 m/s] :",o:["448 Hz","350 Hz","361 Hz","411 Hz"],c:0,s:`For source and observer approaching: f' = f (v + vo)/(v \u2212 vs).
f' = 400 \xD7 (340 + 16.5)/(340 \u2212 22) = 400 \xD7 356.5/318.
f' \u2248 448 Hz.`,sub:"Physics",ch:"Waves"},{id:"neet-2017-q145",pn:145,y:"NEET 2017 \xB7 7 May",tp:"Gravitation",st:"Gravitational attraction",q:"Two astronauts are floating in gravitational free space after having lost contact with their spaceship. The two will :",o:["will become stationary","keep floating at the same distance between them.","move towards each other","move away from each other."],c:2,s:`The only force on each astronaut is the gravitational pull of the other.
Gravity is attractive, so they slowly move towards each other.`,sub:"Physics",ch:"Gravitation"},{id:"neet-2017-q146",pn:146,y:"NEET 2017 \xB7 7 May",tp:"Kinetic Theory",st:"Internal energy of gas mixture",q:"A gas mixture consists of 2 moles of O2 and 4 moles of Ar at temperature T. Neglecting all vibrational modes, the total internal energy of the system is :",o:["11 RT","4 RT","15 RT","9 RT"],c:0,s:`O2 is diatomic with 5 degrees of freedom: U = 2 \xD7 (5/2)RT = 5RT.
Ar is monatomic with 3 degrees of freedom: U = 4 \xD7 (3/2)RT = 6RT.
Total U = 5RT + 6RT = 11RT.`,sub:"Physics",ch:"Kinetic Theory"},{id:"neet-2017-q147",pn:147,y:"NEET 2017 \xB7 7 May",tp:"Semiconductor Electronics",st:"p-n junction diode",q:"Which one of the following represents forward bias diode ?",o:["Diode with 3V on the left, 5V on the right","Diode with 0V on the left, \u22122V on the right","Diode with \u22124V on the left, \u22123V on the right","Diode with \u22122V on the left, +2V on the right"],c:1,s:`A diode is forward biased when its p side (arrow side, left) is at a higher potential than its n side.
Only 0 V on the left and \u22122 V on the right satisfy this.
So option 2 is correct.`,fig:{w:350,h:100,alt:"Four circuits (1) to (4), each a diode pointing right in series with a resistor R, with end potentials 3 V and 5 V, 0 V and -2 V, -4 V and -3 V, -2 V and +2 V.",d:[["t",6,28,"(1)",""],["l",32,24,66,24],["p","M66 17 L66 31 L82 24 Z"],["l",82,17,82,31],["l",82,24,102,24],["p","M102 24 L104 24 L105.5 19 L108.5 29 L111.5 19 L114.5 29 L117.5 19 L120.5 29 L122 24"],["l",122,24,162,24],["t",32,18,"3V",""],["t",162,18,"5V","e"],["t",113,12,"R","m"],["t",176,28,"(2)",""],["l",202,24,236,24],["p","M236 17 L236 31 L252 24 Z"],["l",252,17,252,31],["l",252,24,272,24],["p","M272 24 L274 24 L275.5 19 L278.5 29 L281.5 19 L284.5 29 L287.5 19 L290.5 29 L292 24"],["l",292,24,332,24],["t",202,18,"0V",""],["t",332,18,"\u20132V","e"],["t",283,12,"R","m"],["t",6,80,"(3)",""],["l",32,76,66,76],["p","M66 69 L66 83 L82 76 Z"],["l",82,69,82,83],["l",82,76,102,76],["p","M102 76 L104 76 L105.5 71 L108.5 81 L111.5 71 L114.5 81 L117.5 71 L120.5 81 L122 76"],["l",122,76,162,76],["t",32,70,"\u20134V",""],["t",162,70,"\u20133V","e"],["t",113,64,"R","m"],["t",176,80,"(4)",""],["l",202,76,236,76],["p","M236 69 L236 83 L252 76 Z"],["l",252,69,252,83],["l",252,76,272,76],["p","M272 76 L274 76 L275.5 71 L278.5 81 L281.5 71 L284.5 81 L287.5 71 L290.5 81 L292 76"],["l",292,76,332,76],["t",202,70,"\u20132V",""],["t",332,70,"+2V","e"],["t",283,64,"R","m"]]},sub:"Physics",ch:"Semiconductor Electronics"},{id:"neet-2017-q148",pn:148,y:"NEET 2017 \xB7 7 May",tp:"Electromagnetic Induction",st:"Induced charge",q:"A long solenoid of diameter 0.1 m has 2 \xD7 10\u2074 turns per meter. At the centre of the solenoid, a coil of 100 turns and radius 0.01 m is placed with its axis coinciding with the solenoid axis. The current in the solenoid reduces at a constant rate to 0A from 4 A in 0.05 s. If the resistance of the coil is 10\u03C0\xB2 \u03A9, the total charge flowing through the coil during this time is :",o:["16\u03C0 \xB5C","32\u03C0 \xB5C","16 \xB5C","32 \xB5C"],c:3,s:`Charge q = (change in flux linkage)/R.
Initial B in the solenoid = \u03BC0 n I = 4\u03C0\xD710\u207B\u2077 \xD7 2\xD710\u2074 \xD7 4 = 32\u03C0\xD710\u207B\xB3 T.
Coil area A = \u03C0(10\u207B\xB2)\xB2 = \u03C0\xD710\u207B\u2074 m\xB2.
Initial flux linkage = N B A = 100 \xD7 32\u03C0\xD710\u207B\xB3 \xD7 \u03C0\xD710\u207B\u2074 = 32\u03C0\xB2\xD710\u207B\u2074 Wb.
Final flux = 0, so q = 32\u03C0\xB2\xD710\u207B\u2074 / (10\u03C0\xB2) = 32\xD710\u207B\u2076 C = 32 \xB5C.`,sub:"Physics",ch:"Electromagnetic Induction"},{id:"neet-2017-q149",pn:149,y:"NEET 2017 \xB7 7 May",tp:"System of Particles and Rotational Motion",st:"Torque and angular acceleration",q:"A rope is wound around a hollow cylinder of mass 3 kg and radius 40 cm. What is the angular acceleration of the cylinder if the rope is pulled with a force of 30 N ?",o:["5 m/s\xB2","25 m/s\xB2","0.25 rad/s\xB2","25 rad/s\xB2"],c:3,s:`Torque \u03C4 = F \xD7 R = 30 \xD7 0.4 = 12 N m.
Moment of inertia of a hollow cylinder I = MR\xB2 = 3 \xD7 0.16 = 0.48 kg m\xB2.
\u03B1 = \u03C4/I = 12/0.48 = 25 rad/s\xB2.`,sub:"Physics",ch:"System of Particles and Rotational Motion"},{id:"neet-2017-q150",pn:150,y:"NEET 2017 \xB7 7 May",tp:"Electrostatic Potential and Capacitance",st:"Sharing of charge",q:"A capacitor is charged by a battery. The battery is removed and another identical uncharged capacitor is connected in parallel. The total electrostatic energy of resulting system :",o:["increases by a factor of 2","increases by a factor of 4","decreases by a factor of 2","remains the same"],c:2,s:`Initial energy = \xBDCV\xB2.
Charge Q = CV is shared equally, so the total capacitance is 2C and the common voltage is V/2.
Final energy = \xBD(2C)(V/2)\xB2 = \xBCCV\xB2, which is half the initial value.
So the energy decreases by a factor of 2.`,sub:"Physics",ch:"Electrostatic Potential and Capacitance"},{id:"neet-2017-q151",pn:151,y:"NEET 2017 \xB7 7 May",tp:"Gravitation",st:"Variation of g",q:"The acceleration due to gravity at a height 1 km above the earth is the same as at a depth d below the surface of earth. Then :",o:["d = 2 km","d = 1/2 km","d = 1 km","d = 3/2 km"],c:0,s:`At a small height h: g_h = g(1 \u2212 2h/R).
At a small depth d: g_d = g(1 \u2212 d/R).
Set g_h = g_d: 2h/R = d/R, so d = 2h.
With h = 1 km, d = 2 km.`,sub:"Physics",ch:"Gravitation"},{id:"neet-2017-q152",pn:152,y:"NEET 2017 \xB7 7 May",tp:"Oscillations",st:"SHM: velocity and acceleration",q:"A particle executes linear simple harmonic motion with an amplitude of 3 cm. When the particle is at 2 cm from the mean position, the magnitude of its velocity is equal to that of its acceleration. Then its time period in seconds is :",o:["2\u03C0/\u221A3","\u221A5/\u03C0","\u221A5/(2\u03C0)","4\u03C0/\u221A5"],c:3,s:`In SHM, speed v = \u03C9\u221A(a\xB2 \u2212 x\xB2) and acceleration = \u03C9\xB2x.
Setting them equal: \u03C9\xB2x = \u03C9\u221A(a\xB2 \u2212 x\xB2), so \u03C9 = \u221A(a\xB2 \u2212 x\xB2)/x.
\u03C9 = \u221A(9 \u2212 4)/2 = \u221A5/2 rad/s.
T = 2\u03C0/\u03C9 = 4\u03C0/\u221A5 s.`,sub:"Physics",ch:"Oscillations"},{id:"neet-2017-q153",pn:153,y:"NEET 2017 \xB7 7 May",tp:"Thermodynamics",st:"Carnot refrigerator",q:"A carnot engine having an efficiency of 1/10 as heat engine, is used as a refrigerator. If the work done on the system is 10 J, the amount of energy absorbed from the reservoir at lower temperature is :",o:["100 J","1 J","90 J","99 J"],c:2,s:`As an engine, \u03B7 = W/Q1 = 1/10 for the same two reservoirs.
When run as a refrigerator with W = 10 J, the heat given to the hot reservoir is Q1 = W/\u03B7 = 10 \xD7 10 = 100 J.
Heat absorbed from the cold reservoir Q2 = Q1 \u2212 W = 100 \u2212 10 = 90 J.`,sub:"Physics",ch:"Thermodynamics"},{id:"neet-2017-q154",pn:154,y:"NEET 2017 \xB7 7 May",tp:"Dual Nature of Radiation and Matter",st:"Photoelectric effect",q:"The photoelectric threshold wavelength of silver is 3250 \xD7 10\u207B\xB9\u2070 m. The velocity of the electron ejected from a silver surface by ultraviolet light of wavelength 2536 \xD7 10\u207B\xB9\u2070 m is : (Given h = 4.14 \xD7 10\u207B\xB9\u2075 eVs and c = 3 \xD7 10\u2078 ms\u207B\xB9)",o:["\u2248 0.3 \xD7 10\u2076 ms\u207B\xB9","\u2248 6 \xD7 10\u2075 ms\u207B\xB9","\u2248 0.6 \xD7 10\u2076 ms\u207B\xB9","\u2248 61 \xD7 10\xB3 ms\u207B\xB9"],a:"2,3",s:`hc = 4.14\xD710\u207B\xB9\u2075 \xD7 3\xD710\u2078 = 1.242\xD710\u207B\u2076 eV m = 12420 eV \xC5 (about 12400).
Work function W = hc/\u03BB0 = 12400/3250 = 3.815 eV.
Photon energy = 12400/2536 = 4.89 eV.
Kmax = 4.89 \u2212 3.81 = 1.07 eV.
v = \u221A(2K/m) = \u221A(2 \xD7 1.07 \xD7 1.6\xD710\u207B\xB9\u2079 / 9.1\xD710\u207B\xB3\xB9) \u2248 6\xD710\u2075 m/s.
Options 2 and 3 are the same value (6 \xD7 10\u2075 = 0.6 \xD7 10\u2076).
Note: printed key is '2,3': options 2 and 3 are equal (6 x 10^5 = 0.6 x 10^6 m/s).`,sub:"Physics",ch:"Dual Nature of Radiation and Matter"},{id:"neet-2017-q155",pn:155,y:"NEET 2017 \xB7 7 May",tp:"Electric Charges and Fields",st:"Charge neutrality and gravity",q:"Suppose the charge of a proton and an electron differ slightly. One of them is \u2212 e, the other is (e + \u0394e). If the net of electrostatic force and gravitational force between two hydrogen atoms placed at a distance d (much greater than atomic size) apart is zero, then \u0394e is of the order of [Given mass of hydrogen mh = 1.67 \xD7 10\u207B\xB2\u2077 kg]",o:["10\u207B\u2074\u2077 C","10\u207B\xB2\u2070 C","10\u207B\xB2\xB3 C","10\u207B\xB3\u2077 C"],c:3,s:`Each hydrogen atom has net charge \u0394e (proton and electron charges differ by \u0394e).
Set the electrostatic force equal to the gravitational force: k(\u0394e)\xB2/d\xB2 = G mh\xB2/d\xB2.
(\u0394e)\xB2 = G mh\xB2/k = 6.67\xD710\u207B\xB9\xB9 \xD7 (1.67\xD710\u207B\xB2\u2077)\xB2 / (9\xD710\u2079) \u2248 2\xD710\u207B\u2077\u2074.
\u0394e \u2248 1.4\xD710\u207B\xB3\u2077 C, which is of the order 10\u207B\xB3\u2077 C.`,sub:"Physics",ch:"Electric Charges and Fields"},{id:"neet-2017-q156",pn:156,y:"NEET 2017 \xB7 7 May",tp:"Moving Charges and Magnetism",st:"Force between parallel currents",q:"An arrangement of three parallel straight wires placed perpendicular to plane of paper carrying same current 'I' along the same direction is shown in Fig. Magnitude of force per unit length on the middle wire 'B' is given by :",o:["\u03BC0 i\xB2/(\u221A2 \u03C0 d)","\u03BC0 i\xB2/(2\u03C0 d)","2\u03BC0 i\xB2/(\u03C0 d)","\u221A2 \u03BC0 i\xB2/(\u03C0 d)"],c:0,s:`Parallel wires carrying current in the same direction attract.
Force per unit length on B due to A = \u03BC0 I\xB2/(2\u03C0d), directed toward A.
Force per unit length on B due to C = \u03BC0 I\xB2/(2\u03C0d), directed toward C; these two are at 90\xB0.
Net = \u221A2 \xD7 \u03BC0 I\xB2/(2\u03C0d) = \u03BC0 I\xB2/(\u221A2 \u03C0d).`,fig:{w:220,h:170,alt:"Three parallel wires carrying current out of the page: B at top left, C a distance d to its right, A a distance d directly below B, with a right angle of 90 degrees at B.",d:[["l",50,40,50,125],["l",50,40,150,40],["c",50,40,6],["c",150,40,6],["c",50,125,6],["c",50,40,1.6,"F"],["c",150,40,1.6,"F"],["c",50,125,1.6,"F"],["p","M68 40 A18 18 0 0 1 50 58"],["t",76,63,"90\xB0",""],["t",38,34,"B","e"],["t",154,32,"C",""],["t",36,140,"A","e"],["t",100,32,"d","m"],["t",58,86,"d",""]]},sfig:{w:220,h:190,alt:"At B the force F_BC points horizontally toward C and the force F_BA points vertically down toward A; wires at B, C and A shown as circles with dots.",d:[["l",50,40,110,40,"a"],["t",116,44,"F",""],["t",122,47,"BC","s"],["l",50,40,50,100,"a"],["t",46,108,"F","e"],["t",44,115,"BA","s"],["c",50,40,6],["c",50,40,1.6,"F"],["c",150,40,6],["c",150,40,1.6,"F"],["c",50,160,6],["c",50,160,1.6,"F"],["t",38,34,"B","e"],["t",160,34,"C",""],["t",38,174,"A","e"]]},sub:"Physics",ch:"Moving Charges and Magnetism"},{id:"neet-2017-q157",pn:157,y:"NEET 2017 \xB7 7 May",tp:"Current Electricity",st:"Resistance and stretching",q:"The resistance of a wire is 'R' ohm. If it is melted and stretched to 'n' times its original length, its new resistance will be",o:["R/n\xB2","nR","R/n","n\xB2R"],c:3,s:`R = \u03C1l/A. Stretching keeps the volume (l \xD7 A) constant.
If length becomes nl, area becomes A/n.
R' = \u03C1(nl)/(A/n) = n\xB2\u03C1l/A = n\xB2R.`,sub:"Physics",ch:"Current Electricity"},{id:"neet-2017-q158",pn:158,y:"NEET 2017 \xB7 7 May",tp:"Ray Optics and Optical Instruments",st:"Rotation of a mirror",q:"A beam of light from a source L is incident normally in a plane mirror fixed at a certain distance x from the source. The beam is reflected back as a spot on a scale placed just above the source L. When the mirror is rotated through a small angle \u03B8, the spot of the light is found to move through a distance y on the scale. The angle \u03B8 is given by-",o:["x/y","y/(2x)","y/x","x/(2y)"],c:1,s:`When a mirror turns by \u03B8, the reflected ray turns by 2\u03B8.
The spot moves a distance y on a scale at distance x, so for a small angle 2\u03B8 = y/x.
Therefore \u03B8 = y/(2x).`,fig:{w:220,h:140,alt:"Source S on the left sends a ray of length x to a plane mirror tilted by angle theta from the vertical; the reflected ray makes angle 2 theta with the incident ray and reaches the scale a distance y above S.",d:[["l",145,10,145,125],["l",107,110,180,18],["l",30,67,145,63],["l",145,63,45,20],["l",30,67,45,20],["p","M145 43 A20 20 0 0 1 157.5 47.4"],["t",150,34,"\u03B8",""],["p","M123 64 A22 22 0 0 1 125 52"],["t",90,60,"2\u03B8",""],["t",88,80,"x","m"],["t",14,76,"S",""],["t",24,44,"y","e"]]},sfig:{w:220,h:140,alt:"Solution picture: source S, ray of length x to the tilted mirror, vertical normal, angle theta between normal and mirror, reflected ray making 2theta with the incident ray and reaching the scale a height y above S.",d:[["l",145,10,145,125],["l",107,110,180,18],["l",30,67,145,63],["l",145,63,45,20],["l",30,67,45,20],["p","M145 43 A20 20 0 0 1 157.5 47.4"],["t",150,34,"\u03B8",""],["p","M123 63.8 A22 22 0 0 1 124.8 54.4"],["t",90,60,"2\u03B8",""],["t",88,80,"x","m"],["t",14,76,"S",""],["t",24,44,"y","e"]]},sub:"Physics",ch:"Ray Optics and Optical Instruments"},{id:"neet-2017-q159",pn:159,y:"NEET 2017 \xB7 7 May",tp:"Laws of Motion",st:"Circular motion: net force",q:"One end of string of length l is connected to a particle of mass 'm' and the other end is connected to a small peg on a smooth horizontal table. If the particle moves in circle with speed 'v' the net force on the particle (directed towards center) will be (T represents the tension in the string)",o:["Zero","T","T + mv\xB2/l","T \u2212 mv\xB2/l"],c:1,s:`On a smooth horizontal table the only horizontal force on the particle is the tension, directed toward the centre.
So the net force toward the centre is T.
(This T equals mv\xB2/l.)`,sfig:{w:180,h:70,alt:"Particle (dot) with tension T drawn toward the peg on the left and the centripetal requirement mv\xB2/l drawn to the right along the same line.",d:[["l",12,36,118,36,"a"],["l",69,36,44,36,"a"],["c",69,36,2.6,"F"],["t",30,28,"T","m"],["t",150,29,"mv\xB2","m"],["l",134,34,166,34],["t",150,50,"l","m"]]},sub:"Physics",ch:"Laws of Motion"},{id:"neet-2017-q160",pn:160,y:"NEET 2017 \xB7 7 May",tp:"Units and Measurements",st:"Dimensional analysis",q:"A physical quantity of the dimensions of length that can be formed out of c, G and e\xB2/(4\u03C0\u03B50) is [c is velocity of light, G is universal constant of gravitation and e is charge] ;",o:["(1/c) G e\xB2/(4\u03C0\u03B50)","(1/c\xB2) [G e\xB2/(4\u03C0\u03B50)]^(1/2)","c\xB2 [G e\xB2/(4\u03C0\u03B50)]^(1/2)","(1/c\xB2) [e\xB2/(G 4\u03C0\u03B50)]^(1/2)"],c:1,s:`Let L = c^x G^y (e\xB2/4\u03C0\u03B50)^z.
Dimensions: c = LT\u207B\xB9; G = M\u207B\xB9L\xB3T\u207B\xB2; e\xB2/4\u03C0\u03B50 = ML\xB3T\u207B\xB2.
Mass: \u2212y + z = 0.
Length: x + 3y + 3z = 1.
Time: \u2212x \u2212 2y \u2212 2z = 0.
Solving: y = z, x = \u22124y, so x + 6y = 1 gives y = 1/2, x = \u22122.
L = c\u207B\xB2 G^(1/2) (e\xB2/4\u03C0\u03B50)^(1/2) = (1/c\xB2)[G e\xB2/(4\u03C0\u03B50)]^(1/2).`,sub:"Physics",ch:"Units and Measurements"},{id:"neet-2017-q161",pn:161,y:"NEET 2017 \xB7 7 May",tp:"Ray Optics and Optical Instruments",st:"Prisms: dispersion without deviation",q:"A thin prism having refracting angle 10\xB0 is made of glass of refractive index 1.42. This prism is combined with another thin prism of glass of refractive index 1.7. This combination produces dispersion without deviation. The refracting angle of second prism should be :",o:["10\xB0","4\xB0","6\xB0","8\xB0"],c:2,s:`For no net deviation, the deviations cancel: (\u03BC \u2212 1)A + (\u03BC\u2032 \u2212 1)A\u2032 = 0.
So A\u2032 = \u2212A(\u03BC \u2212 1)/(\u03BC\u2032 \u2212 1) = \u221210 \xD7 0.42/0.7 = \u22126\xB0.
The minus sign only means the second prism is inverted, so its angle is 6\xB0.`,sub:"Physics",ch:"Ray Optics and Optical Instruments"},{id:"neet-2017-q162",pn:162,y:"NEET 2017 \xB7 7 May",tp:"Atoms",st:"Hydrogen spectrum",q:"The ratio of wavelengths of the last line of Balmer series and the last line of Lyman series is :",o:["0.5","2","1","4"],c:3,s:`The last line of a series is for n \u2192 \u221E.
Lyman: 1/\u03BB = R(1/1\xB2 \u2212 1/\u221E\xB2) = R, so \u03BB = 1/R.
Balmer: 1/\u03BB = R(1/2\xB2 \u2212 1/\u221E\xB2) = R/4, so \u03BB = 4/R.
Ratio \u03BB(Balmer)/\u03BB(Lyman) = 4.`,sub:"Physics",ch:"Atoms"},{id:"neet-2017-q163",pn:163,y:"NEET 2017 \xB7 7 May",tp:"Waves",st:"Closed organ pipe",q:"The two nearest harmonics of a tube closed at one end and open at other end are 220 Hz and 260 Hz. What is the fundamental frequency of the system ?",o:["40 Hz","10 Hz","20 Hz","30 Hz"],c:2,s:`A closed pipe has only odd harmonics: f = n(v/4L) with n = 1, 3, 5, \u2026
Two nearest harmonics differ by 2 \xD7 fundamental, so 260 \u2212 220 = 40 = 2f0.
f0 = 20 Hz. (Check: 220 = 11 \xD7 20, 260 = 13 \xD7 20.)`,sub:"Physics",ch:"Waves"},{id:"neet-2017-q164",pn:164,y:"NEET 2017 \xB7 7 May",tp:"Current Electricity",st:"Potentiometer",q:"A potentiometer is an accurate and versatile device to make electrical measurements of E.M.F. because the method involves :",o:["a combination of cells, galvanometer and resistances","cells","potential gradients","a condition of no current flow through the galvanometer"],c:3,s:`At the balance (null) point no current flows through the galvanometer.
So the potentiometer draws no current from the cell being measured.
This means there is no internal-resistance drop and the measured value is the true emf.`,sub:"Physics",ch:"Current Electricity"},{id:"neet-2017-q165",pn:165,y:"NEET 2017 \xB7 7 May",tp:"Laws of Motion",st:"Spring and string cut",q:"Two blocks A and B of masses 3m and m respectively are connected by a massless and inextensible string. The whole system is suspended by a massless spring as shown in figure. The magnitudes of acceleration of A and B immediately after the string is cut, are respectively :",o:["g/3, g/3","g, g/3","g/3, g","g, g"],c:2,s:`Before cutting, the spring force is kx = (3m + m)g = 4mg.
When the string is cut, the spring force cannot change at once, so it is still 4mg upward on A.
On A: 4mg \u2212 3mg = 3m a, so a = g/3 (upward).
B is free-falling with only gravity: a = g.`,fig:{w:130,h:180,d:[["l",36,12,84,12],["l",38,12,32,5],["l",45,12,39,5],["l",52,12,46,5],["l",59,12,53,5],["l",66,12,60,5],["l",73,12,67,5],["l",80,12,74,5],["l",60,12,60,22],["p","M60 22 C68 22 68 27 60 28 C52 29 52 34 60 34 C68 34 68 39 60 40 C52 41 52 46 60 46 C68 46 68 51 60 52 C52 53 52 58 60 58 C68 58 68 63 60 64 C52 65 52 70 60 70 C68 70 68 75 60 76 C52 77 52 82 60 82 C68 82 68 87 60 88 C52 89 52 94 60 94"],["l",60,94,60,106],["r",43,106,34,26],["t",60,124,"A","m"],["t",82,123,"3m",""],["l",60,132,60,148],["r",46,148,28,22],["t",60,164,"B","m"],["t",79,164,"m",""]],alt:"A massless spring hangs from a ceiling; block A of mass 3m hangs on its lower end and block B of mass m hangs below A joined by a string."},sfig:{w:140,h:208,d:[["l",36,12,84,12],["l",38,12,32,5],["l",45,12,39,5],["l",52,12,46,5],["l",59,12,53,5],["l",66,12,60,5],["l",73,12,67,5],["l",80,12,74,5],["l",60,12,60,22],["p","M60 22 C68 22 68 27 60 28 C52 29 52 34 60 34 C68 34 68 39 60 40 C52 41 52 46 60 46 C68 46 68 51 60 52 C52 53 52 58 60 58 C68 58 68 63 60 64 C52 65 52 70 60 70 C68 70 68 75 60 76 C52 77 52 82 60 82 C68 82 68 87 60 88 C52 89 52 94 60 94"],["l",60,94,60,106],["r",43,106,34,26],["t",60,124,"A","m"],["t",82,123,"3m",""],["l",60,154,60,134,"a"],["l",60,154,60,174,"a"],["r",46,176,28,22],["t",60,192,"B","m"],["t",79,192,"m",""],["t",72,64,"kx = 4mg","s"]],alt:"After the string is cut: the spring still pulls A up with kx = 4mg, and B, mass m, falls freely."},sub:"Physics",ch:"Laws of Motion"},{id:"neet-2017-q166",pn:166,y:"NEET 2017 \xB7 7 May",tp:"Magnetism and Matter",st:"Apparent dip",q:"If \u03B81 and \u03B82 be the apparent angles of dip observed in two vertical planes at right angles to each other, then the true angle of dip \u03B8 is given by :",o:["tan\xB2 \u03B8 = tan\xB2 \u03B81 \u2212 tan\xB2 \u03B82","cot\xB2 \u03B8 = cot\xB2 \u03B81 + cot\xB2 \u03B82","tan\xB2 \u03B8 = tan\xB2 \u03B81 + tan\xB2 \u03B82","cot\xB2 \u03B8 = cot\xB2 \u03B81 \u2212 cot\xB2 \u03B82"],c:1,s:`If a vertical plane makes angle \u03B1 with the magnetic meridian, the apparent dip \u03B8\u2032 satisfies tan \u03B8\u2032 = tan \u03B8 / cos \u03B1.
Plane 1 at \u03B1: tan \u03B81 = tan \u03B8 / cos \u03B1, so cos \u03B1 = tan \u03B8 / tan \u03B81.
Plane 2 is at 90\xB0 \u2212 \u03B1: tan \u03B82 = tan \u03B8 / sin \u03B1, so sin \u03B1 = tan \u03B8 / tan \u03B82.
Use sin\xB2\u03B1 + cos\xB2\u03B1 = 1: tan\xB2\u03B8/tan\xB2\u03B81 + tan\xB2\u03B8/tan\xB2\u03B82 = 1.
Dividing by tan\xB2\u03B8 gives cot\xB2\u03B8 = cot\xB2\u03B81 + cot\xB2\u03B82.`,sfig:{w:400,h:370,alt:"Perspective sketch of two vertical planes at right angles; the magnetic meridian plane makes angle alpha with vertical plane (1).",d:[["l",151,155,291,128,""],["l",151,155,148,348,""],["l",148,348,291,310,""],["l",291,128,291,310,""],["l",255,8,291,128,""],["l",188,95,291,128,""],["l",255,8,255,270,"d"],["l",255,270,291,310,"d"],["l",188,95,188,295,"d"],["l",188,295,291,310,"d"],["l",130,260,143,246,"a"],["t",278,62,"vertical plane(2)",""],["t",91,110,"magnetic",""],["t",91,128,"meridian",""],["t",28,278,"vertical plane(1)",""],["t",218,131,"\u03B1",""],["p","M245 113 A48 48 0 0 0 244 137"]]},sub:"Physics",ch:"Magnetism and Matter"},{id:"neet-2017-q167",pn:167,y:"NEET 2017 \xB7 7 May",tp:"Mechanical Properties of Solids",st:"Bulk modulus",q:"The bulk modulus of a spherical object is 'B'. If it is subjected to uniform pressure 'p', the fractional decrease in radius is :",o:["p/(3B)","p/B","B/(3p)","3p/B"],c:0,s:`Bulk modulus B = p/(\u0394V/V), so \u0394V/V = p/B.
For a sphere V \u221D r\xB3, so \u0394V/V = 3\u0394r/r.
Therefore \u0394r/r = p/(3B).`,sub:"Physics",ch:"Mechanical Properties of Solids"},{id:"neet-2017-q168",pn:168,y:"NEET 2017 \xB7 7 May",tp:"Electromagnetic Induction",st:"L and C at switch-on",q:"Figure shows a circuit that contains three identical resistors with resistance R = 9.0 \u03A9 each, two identical inductors with inductance L = 2.0 mH each, and an ideal battery with emf \u03B5 = 18 V. The current 'I' through the battery just after the switch closed is,\u2026\u2026..",o:["0 ampere","2 mA","0.2 A","2 A"],a:"Answer not available",s:`Just after the switch closes, an inductor acts as an open circuit and a capacitor acts as a short circuit.
Branch 1 (L in series with R) carries no current. Branch 2 is R alone. Branch 3 is R in series with (L parallel C), and the shorted C removes L, so it is R alone.
Two resistors R in parallel give R/2 = 4.5 \u03A9.
I = 18/4.5 = 4 A, which is not among the options.
Note: printed key 'Answer not available'; my working gives 4 A, which is not one of the options.`,fig:{w:296,h:173,alt:"Battery of emf \u03B5 with a switch feeds three parallel branches: L in series with R; R alone; R in series with L, where L has a capacitor C connected across it.",d:[["l",19.2,24,219.2,24,""],["l",70.4,152,265.6,152,""],["l",19.2,152,41.6,152,""],["c",41.6,152,2.2,"F"],["c",70.4,152,2.2,"F"],["l",41.6,152,68.8,136,""],["l",19.2,24,19.2,67.2,""],["l",6.4,67.2,32,67.2,""],["l",12.8,75.2,25.6,75.2,""],["l",19.2,75.2,19.2,99.2,""],["t",14.4,57.6,"+","e"],["t",6.4,96,"\u03B5","e"],["l",19.2,99.2,19.2,152,""],["c",99.2,24,2.2,"F"],["c",99.2,152,2.2,"F"],["c",155.2,24,2.2,"F"],["c",155.2,152,2.2,"F"],["c",219.2,24,2.2,"F"],["c",219.2,152,2.2,"F"],["l",99.2,24,99.2,38.4,""],["p","M99.2 38.4 A4.4 4.4 0 0 1 99.2 47.2 A4.4 4.4 0 0 1 99.2 56 A4.4 4.4 0 0 1 99.2 64.8 A4.4 4.4 0 0 1 99.2 73.6"],["l",99.2,73.6,99.2,89.6,""],["p","M99.2 89.6 L99.2 92.8 L104.8 94.9 L93.6 99.2 L104.8 103.5 L93.6 107.7 L104.8 112 L93.6 116.3 L99.2 118.4 L99.2 121.6"],["l",99.2,121.6,99.2,152,""],["t",84.8,57.6,"L","e"],["t",84.8,110.4,"R","e"],["l",155.2,24,155.2,44.8,""],["p","M155.2 44.8 L155.2 48 L160.8 50.7 L149.6 56 L160.8 61.3 L149.6 66.7 L160.8 72 L149.6 77.3 L155.2 80 L155.2 83.2"],["l",155.2,83.2,155.2,152,""],["t",168,70.4,"R",""],["l",219.2,24,219.2,38.4,""],["p","M219.2 38.4 L219.2 41.6 L224.8 44 L213.6 48.8 L224.8 53.6 L213.6 58.4 L224.8 63.2 L213.6 68 L219.2 70.4 L219.2 73.6"],["l",219.2,73.6,219.2,92.8,""],["c",219.2,92.8,2.2,"F"],["p","M219.2 92.8 A4.4 4.4 0 0 1 219.2 101.6 A4.4 4.4 0 0 1 219.2 110.4 A4.4 4.4 0 0 1 219.2 119.2 A4.4 4.4 0 0 1 219.2 128"],["l",219.2,128,219.2,152,""],["t",232,64,"R",""],["t",232,118.4,"L",""],["l",219.2,92.8,265.6,92.8,""],["l",265.6,92.8,265.6,121.6,""],["l",256,121.6,275.2,121.6,""],["l",256,129.6,275.2,129.6,""],["l",265.6,129.6,265.6,152,""],["t",281.6,134.4,"C",""]]},sub:"Physics",ch:"Electromagnetic Induction"},{id:"neet-2017-q169",pn:169,y:"NEET 2017 \xB7 7 May",tp:"Thermal Properties of Matter",st:"Thermal conductivity of composite rod",q:"Two rods A and B of different materials are welded together as shown in figure. Their thermal conductivities are K1 and K2. The thermal conductivity of the composite rod will be",o:["2(K1 + K2)","(K1 + K2)/2","3(K1 + K2)/2","K1 + K2"],c:1,s:`The rods lie side by side with the same length and area, between the same end temperatures T1 and T2, so heat flows through them in parallel.
Total heat flow = (K1 A + K2 A)\u0394T/d. The composite has area 2A: K_eq \xD7 2A \xD7 \u0394T/d.
Equating: K_eq = (K1 + K2)/2.`,fig:{w:200,h:125,alt:"Composite rod of length d: upper half rod A (K1) and lower half rod B (K2) welded along their length, left end at T1 and right end at T2.",d:[["l",40,74,48,82],["l",40,60,52,72],["l",54,74,62,82],["l",40,46,52,58],["l",68,74,76,82],["l",40,32,52,44],["l",54,46,66,58],["l",76,68,90,82],["l",44,22,52,30],["l",68,46,104,82],["l",58,22,66,30],["l",76,40,100,64],["l",110,74,118,82],["l",72,22,108,58],["l",124,74,132,82],["l",86,22,100,36],["l",110,46,122,58],["l",124,60,146,82],["l",100,22,108,30],["l",124,46,160,82],["l",114,22,122,30],["l",124,32,160,68],["l",128,22,160,54],["l",142,22,160,40],["l",156,22,160,26],["r",40,22,120,60],["l",40,52,160,52],["t",64,42,"A","m"],["t",112,42,"K\u2081","m"],["t",64,70,"B","m"],["t",112,70,"K\u2082","m"],["t",34,56,"T\u2081","e"],["t",166,56,"T\u2082",""],["l",40,98,160,98,"b"],["t",100,114,"d","m"]]},sub:"Physics",ch:"Thermal Properties of Matter"},{id:"neet-2017-q170",pn:170,y:"NEET 2017 \xB7 7 May",tp:"Motion in a Straight Line",st:"Relative velocity",q:"Preeti reached the metro station and found that the escalator was not working. She walked up the stationary escalator in time t1. On other days, if she remains stationary on the moving escalator, then the escalator takes her up in time t2. The time taken by her to walk up on the moving escalator will be :",o:["t1 \u2212 t2","(t1 + t2)/2","t1t2/(t2 \u2212 t1)","t1t2/(t2 + t1)"],c:3,s:`Let the length be d. Her walking speed is d/t1 and the escalator speed is d/t2.
Walking on the moving escalator, the speeds add: d/t = d/t1 + d/t2.
1/t = (t1 + t2)/(t1 t2), so t = t1t2/(t1 + t2).`,sub:"Physics",ch:"Motion in a Straight Line"},{id:"neet-2017-q171",pn:171,y:"NEET 2017 \xB7 7 May",tp:"System of Particles and Rotational Motion",st:"Angular momentum conservation",q:"Two discs of same moment of inertia rotating about their regular axis passing through centre and perpendicular to the plane of disc with angular velocities \u03C91 and \u03C92. They are brought into contact face to face coinciding the axis of rotation. The expression for loss of energy during this process is :",o:["(I/8)(\u03C91 \u2212 \u03C92)\xB2","(1/2) I (\u03C91 + \u03C92)\xB2","(1/4) I (\u03C91 \u2212 \u03C92)\xB2","I (\u03C91 \u2212 \u03C92)\xB2"],c:2,s:`Angular momentum is conserved: I\u03C91 + I\u03C92 = 2I\u03C9\u2032, so \u03C9\u2032 = (\u03C91 + \u03C92)/2.
Loss = \xBDI\u03C91\xB2 + \xBDI\u03C92\xB2 \u2212 \xBD(2I)\u03C9\u2032\xB2.
= \xBDI(\u03C91\xB2 + \u03C92\xB2) \u2212 I(\u03C91 + \u03C92)\xB2/4.
= (I/4)(2\u03C91\xB2 + 2\u03C92\xB2 \u2212 \u03C91\xB2 \u2212 \u03C92\xB2 \u2212 2\u03C91\u03C92) = (I/4)(\u03C91 \u2212 \u03C92)\xB2.`,sub:"Physics",ch:"System of Particles and Rotational Motion"},{id:"neet-2017-q172",pn:172,y:"NEET 2017 \xB7 7 May",tp:"System of Particles and Rotational Motion",st:"Centre of mass and couples",q:`Which of the following statements are correct ?
(a) Centre of mass of a body always coincides with the centre of gravity of the body.
(b) Centre of mass of a body is the point at which the total gravitational torque on the body is zero.
(c) A couple on a body produce both translational and rotational motion in a body
(d) Mechanical advantage greater than one means that small effort can be used to lift a large load.`,o:["(c) and (d)","(b) and (d)","(a) and (b)","(b) and (c)"],c:1,s:`(a) is wrong: they coincide only when g is uniform over the body.
(b) is correct: the torque of the weight about the centre of mass is zero.
(c) is wrong: a couple has zero net force, so it produces only rotation.
(d) is correct: mechanical advantage = load/effort, so a value above one means a small effort lifts a large load.
So (b) and (d).`,sub:"Physics",ch:"System of Particles and Rotational Motion"},{id:"neet-2017-q173",pn:173,y:"NEET 2017 \xB7 7 May",tp:"Thermal Properties of Matter",st:"Stefan's law",q:"A spherical black body with a radius of 12 cm radiates 450 watt power at 500 K. If the radius were halved and the temperature doubled, the power radiated in watt would be :",o:["1800","225","450","1000"],c:0,s:`P = \u03C3(4\u03C0R\xB2)T\u2074, so P \u221D R\xB2T\u2074.
P2/P1 = (R/2 \xF7 R)\xB2 \xD7 (2T/T)\u2074 = (1/4) \xD7 16 = 4.
P2 = 4 \xD7 450 = 1800 W.`,sub:"Physics",ch:"Thermal Properties of Matter"},{id:"neet-2017-q174",pn:174,y:"NEET 2017 \xB7 7 May",tp:"Electromagnetic Waves",st:"EM wave fields",q:"In an electromagnetic wave in free space the root mean square value of the electric field is Erms = 6 V/m. The peak value of the magnetic field is :",o:["4.23 \xD7 10\u207B\u2078 T","1.41 \xD7 10\u207B\u2078 T","2.83 \xD7 10\u207B\u2078 T","0.70 \xD7 10\u207B\u2078 T"],c:2,s:`Peak electric field E0 = \u221A2 \xD7 Erms = 6\u221A2 \u2248 8.49 V/m.
B0 = E0/c = 8.49/(3\xD710\u2078) = 2.83 \xD7 10\u207B\u2078 T.`,sub:"Physics",ch:"Electromagnetic Waves"},{id:"neet-2017-q175",pn:175,y:"NEET 2017 \xB7 7 May",tp:"Mechanical Properties of Fluids",st:"U-tube pressure",q:"A U tube with both ends open to the atmosphere, is partially filled with water. Oil, which is immiscible with water, is poured into one side until it stands at a distance of 10 mm above the water level on the other side. Meanwhile the water rises by 65 mm from its original level (see diagram). The density of the oil is :",o:["928 kg m\u207B\xB3","650 kg m\u207B\xB3","425 kg m\u207B\xB3","800 kg m\u207B\xB3"],c:0,s:`Points B and C are at the same level in the water, so their pressures are equal: P_B = P_C.
On the oil side, the oil column above B is 140 mm (65 + 65 + 10).
On the water side, the water column above C is 130 mm (65 + 65).
Pa + \u03C1oil g (140 mm) = Pa + \u03C1water g (130 mm).
\u03C1oil = 1000 \xD7 130/140 = 928 kg/m\xB3.`,fig:{w:290,h:190,alt:"U-tube open to the atmosphere (Pa) with oil in the left arm from A to B and water in the right arm: initial water level D, final water level E 65 mm higher, oil surface 10 mm above E at F; B and C are at the same level.",d:[["l",47,28,47,130],["l",65,28,65,130],["l",133,28,133,130],["l",151,28,151,130],["p","M47 130 A52 52 0 0 0 151 130"],["p","M65 130 A34 34 0 0 0 133 130"],["l",51,44,61,44],["l",51,53,61,53],["l",51,62,61,62],["l",51,71,61,71],["l",51,80,61,80],["l",51,89,61,89],["l",51,98,61,98],["l",51,107,61,107],["l",51,116,61,116],["l",51,125,61,125],["l",137,64,147,64],["l",137,73,147,73],["l",137,82,147,82],["l",137,91,147,91],["l",137,100,147,100],["l",137,109,147,109],["l",137,118,147,118],["l",60,138,70,138],["l",76,146,86,146],["l",94,150,104,150],["l",112,146,122,146],["l",128,138,138,138],["l",65,37,165,37,"d"],["l",98,57,165,57,"d"],["l",98,94,165,94,"d"],["l",65,129,150,129,"d"],["l",169,37,169,57],["l",165,37,173,37],["l",165,57,173,57],["l",104,57,104,94,"b"],["l",104,94,104,129,"b"],["t",55,12,"Pa","m"],["t",143,12,"Pa","m"],["t",38,33,"A","e"],["t",38,139,"B","e"],["t",38,98,"Oil","e"],["t",124,33,"F","e"],["t",124,53,"E","e"],["t",124,90,"D","e"],["t",158,139,"C",""],["t",176,52,"10 mm","s"],["t",176,70,"Final water level","s"],["t",176,98,"Initial water level","s"],["t",156,160,"water","s"],["t",98,79,"65mm","es"],["t",98,116,"65mm","es"]]},sub:"Physics",ch:"Mechanical Properties of Fluids"},{id:"neet-2017-q176",pn:176,y:"NEET 2017 \xB7 7 May",tp:"Wave Optics",st:"Young's double slit",q:"Young's double slit experiment is first performed in air and then in a medium other than air. It is found that 8th bright fringe in the medium lies where 5th dark fringe lies in air. The refractive index of the medium is nearly :",o:["1.78","1.25","1.59","1.69"],c:0,s:`In air, the 5th dark fringe is at y = (2\xD75 \u2212 1)\u03BBD/(2d) = 9\u03BBD/(2d).
In the medium, wavelength is \u03BB/\u03BC, so the 8th bright fringe is at y = 8\u03BBD/(\u03BCd).
Equating: 8/\u03BC = 9/2, so \u03BC = 16/9 \u2248 1.78.`,sub:"Physics",ch:"Wave Optics"},{id:"neet-2017-q177",pn:177,y:"NEET 2017 \xB7 7 May",tp:"Dual Nature of Radiation and Matter",st:"de Broglie wavelength",q:"The de-Broglie wavelength of a neutron in thermal equilibrium with heavy water at a temperature T (Kelvin) and mass m, is :",o:["2h/\u221A(mkT)","h/\u221A(mkT)","h/\u221A(3mkT)","2h/\u221A(3mkT)"],c:2,s:`A thermal neutron has kinetic energy K = (3/2)kT.
de Broglie wavelength \u03BB = h/\u221A(2mK).
\u03BB = h/\u221A(2m \xD7 (3/2)kT) = h/\u221A(3mkT).`,sub:"Physics",ch:"Dual Nature of Radiation and Matter"},{id:"neet-2017-q178",pn:178,y:"NEET 2017 \xB7 7 May",tp:"Motion in a Plane",st:"Acceleration from coordinates",q:"The x and y coordinates of the particle at any time are x = 5t \u2212 2t\xB2 and y = 10t respectively, where x and y are in meters and t in seconds. The acceleration of the particle at t = 2 s is :",o:["\u22128 m/s\xB2","0","5 m/s\xB2","\u22124 m/s\xB2"],c:3,s:`vx = dx/dt = 5 \u2212 4t and vy = dy/dt = 10.
ax = dvx/dt = \u22124 m/s\xB2 and ay = 0.
The acceleration is constant, so at t = 2 s it is \u22124 m/s\xB2.`,sub:"Physics",ch:"Motion in a Plane"},{id:"neet-2017-q179",pn:179,y:"NEET 2017 \xB7 7 May",tp:"Electrostatic Potential and Capacitance",st:"Work in electric field",q:"The diagrams below show regions of equipotentials. A positive charge is moved from A to B in each diagram.",o:["Maximum work is required to move q in figure (b).","Maximum work is required to move q in figure (c).","In all the four cases the work done is the same .","Minimum work is required to move q in figure (a)."],c:2,s:`Work done on a charge by moving it in an electric field is W = q(VB \u2212 VA).
It depends only on the potentials at the start and end, not on the path.
In all four diagrams A and B lie on the same pair of equipotentials, so the work is the same.`,fig:{w:600,h:215,alt:"Four diagrams (a) to (d) of equipotential lines with potentials 10 V to 40 V; a positive charge moves from A to B in each: (a) straight lines, (b) wavy lines, (c) unequally spaced straight lines, (d) concentric arcs.",d:[["l",38,53,38,137],["l",61,53,61,137],["l",84,53,84,137],["l",107,53,107,137],["l",38,94,107,94],["c",38,94,2.4,"F"],["c",107,94,2.4,"F"],["t",68,47,"20 V","m"],["t",120,47,"40 V","m"],["t",36,157,"10 V","m"],["t",92,154,"30 V","m"],["t",26,98,"A","e"],["t",119,98,"B","m"],["p","M172 53 C181 68 163 82 172 95 C181 108 163 123 172 137"],["p","M198 53 C189 68 207 82 198 95 C189 108 207 123 198 137"],["p","M223 53 C232 68 214 82 223 95 C232 108 214 123 223 137"],["p","M250 53 C241 68 259 82 250 95 C241 108 259 123 250 137"],["c",172,95,2.4,"F"],["c",250,95,2.4,"F"],["t",161,99,"A","e"],["t",262,98,"B","m"],["t",193,47,"20 V","m"],["t",247,47,"40 V","m"],["t",175,155,"10 V","m"],["t",230,153,"30 V","m"],["l",323,53,323,137],["l",337,53,337,137],["l",370,53,370,137],["l",393,53,393,137],["c",323,94,2.4,"F"],["c",393,94,2.4,"F"],["t",310,98,"A","e"],["t",405,98,"B","m"],["t",321,47,"10 V","m"],["t",373,47,"30 V","m"],["t",340,155,"20 V","m"],["t",401,155,"40 V","m"],["p","M452 57 C480 75 480 125 468 147"],["p","M463 40 C498 65 502 130 480 155"],["p","M485 33 C525 57 530 125 510 153"],["p","M516 27 C565 57 565 125 522 153"],["c",475,98,2.4,"F"],["c",553,90,2.4,"F"],["t",461,102,"A","e"],["t",565,94,"B","m"],["t",461,40,"20 V","e"],["t",525,18,"40 V","m"],["t",441,155,"10 V","m"],["t",506,167,"30 V","m"],["t",64,191,"(a)","m"],["t",207,191,"(b)","m"],["t",356,191,"(c)","m"],["t",496,191,"(d)","m"]]},sub:"Physics",ch:"Electrostatic Potential and Capacitance"},{id:"neet-2017-q180",pn:180,y:"NEET 2017 \xB7 7 May",tp:"Oscillations",st:"Springs in series and parallel",q:"A spring of force constant k is cut into lengths of ratio 1 : 2 : 3. They are connected in series and the new force constant is k\u2032. Then they are connected in parallel and force constant is k\u2033. Then k\u2032 : k\u2033 is :",o:["1 : 14","1 : 6","1 : 9","1 : 11"],c:3,s:`A spring of length l has constant inversely proportional to its length.
Pieces are l/6, l/3 and l/2 of the whole, so their constants are 6k, 3k and 2k.
Series: 1/k\u2032 = 1/6k + 1/3k + 1/2k = 1/k, so k\u2032 = k.
Parallel: k\u2033 = 6k + 3k + 2k = 11k.
k\u2032 : k\u2033 = 1 : 11.`,sub:"Physics",ch:"Oscillations"}]})();
